{
  "name": "colors-explorer",
  "private": true,
  "scripts": {
    "develop": "next",
    "build": "next build"
  },
  "dependencies": {
    "@carbon/colors": "link:../../",
    "@carbon/themes": "link:../../../themes",
    "next": "^16.3.6",
    "react": "^19.2.5",
    "react-dom": "^19.2.5",
    "sass": "^1.36.0"
  },
  "resolutions": {
    "nanoid": "^3.3.18"
  }
}

