import React from 'react';
import { colors, hoverColors } from '@carbon/colors';

function getHoverColor(swatch, grade) {
  for (const [key, value] of Object.entries(hoverColors)) {
    if (!key.includes(swatch)) {
      continue;
    }

    if (value[grade]) {
      return value[grade];
    }

    return value;
  }

  throw new Error(`Unable to find hover color for: ${swatch}-${grade}`);
}

function Table({ children }) {
  return (
    <table>
      <thead>
        <tr>
          <th>Token</th>
          <th>Value</th>
          <th>Hover</th>
        </tr>
      </thead>
      <tbody>{children}</tbody>
    </table>
  );
}

function Code({ children }) {
  return (
    <pre>
      <code>{children}</code>
    </pre>
  );
}

