          {Object.keys(colors).map(swatch => {
            return (
              <React.Fragment key={swatch}>
                {Object.keys(colors[swatch]).map(grade => {
                  const hoverColor = getHoverColor(swatch, grade);
                  return (
                    <tr key={`${swatch}-${grade}`}>
