    width: $value;
    height: $value;
    background-color: black;
    margin-right: $spacing-06;
    margin-bottom: $spacing-06;
  }

  $index: $index + 1;
}

$index: 1;

@each $key, $value in $fluid-spacing {
  .fluid-spacing-scale-#{$index} {
    width: $value;
    height: $value;
    background-color: black;
    margin-right: $spacing-06;
    margin-bottom: $spacing-06;
  }

  $index: $index + 1;
}

