$beacon-animation-time: 2s;

/// CoachmarkBeacon styles
/// @access public
/// @group coachmark
@mixin coachmark-beacon {
  $block-class: #{$prefix}--coachmark-beacon;

  .#{$block-class} {
    position: relative;

    &-default {
      .#{$block-class}__target {
        &::before {
          display: none;
        }

        // the blue dot
        &::after {
          position: absolute;
          border-radius: 50%;
          background-color: $blue-50;
          block-size: $spacing-04;
          content: '';
          inline-size: $spacing-04;
          inset-block-start: calc($spacing-01 + $spacing-03);
          inset-inline-start: calc($spacing-01 + $spacing-03);
        }

        &:focus {
          outline: transparent;

          &::before {
            position: absolute;
            display: block;
            border-radius: 100%;
            block-size: 18px;
            content: '';
            inline-size: 18px;
            inset-block-start: 7px;
            inset-inline-start: 7px;
            outline: $spacing-01 $focus solid;
          }
        }
      }
    }

    .#{$block-class}__target {
      // the hit area
      display: flex;
      padding: 0;
      border: none;
      border-radius: 50%;
      background-color: transparent;
      block-size: $spacing-07;
      cursor: pointer;
      inline-size: $spacing-07;

      &[aria-expanded='true'] {
        circle {
          animation: none;
        }
      }
    }

    &__center {
      position: absolute;
      z-index: 6900;
      block-size: $spacing-11;
      inline-size: $spacing-11;
      inset-block-start: calc(($spacing-06 - $spacing-01) * -1);
      inset-inline-start: calc(($spacing-06 - $spacing-01) * -1);
      pointer-events: none;

      circle {
        animation: ripple $beacon-animation-time infinite;
        fill: $support-info;
        fill-opacity: 0;
        -webkit-mask-image: none;
        mask-image: none;
        stroke: $support-info;
        stroke-opacity: 0;
        stroke-width: 1px;
        transition-timing-function: motion(exit, productive);

        @media (prefers-reduced-motion) {
          animation: none;
        }
      }
    }
  }

  @keyframes ripple {
    0% {
      fill-opacity: 0;
      r: 1px;
      stroke-opacity: 0;
      transition-timing-function: motion(entrance, productive);
    }

    31% {
      fill-opacity: 0.2;
      stroke-opacity: 1;
    }

    62% {
      fill-opacity: 0;
      r: 32px;
      stroke-opacity: 0;
    }

    100% {
      fill-opacity: 0;
      r: 32px;
      stroke-opacity: 0;
    }
  }

  @keyframes ring-ripple {
    0% {
      fill-opacity: 0;
      r: 12px;
      stroke-opacity: 0;
      transition-timing-function: motion(entrance, productive);
    }

    31% {
      fill-opacity: 0.2;
      stroke-opacity: 1;
    }

    62% {
      fill-opacity: 0;
      r: 32px;
      stroke-opacity: 0;
    }

    100% {
      fill-opacity: 0;
      r: 32px;
      stroke-opacity: 0;
    }
  }
}

