    color: $text-primary;
    min-block-size: layout.size('height');
  }

  .#{$prefix}--contained-list-item:not(:last-of-type)::before {
    position: absolute;
    background-color: $border-subtle;
    block-size: 1px;
    content: '';
    inset-block-end: 0;
    inset-inline: 0;

