    &.#{$prefix}--data-table--xl tr:not(.#{$prefix}--expandable-row) {
      min-block-size: convert.to-rem(64px);
    }

    // Expansion overrides
    &.#{$prefix}--data-table--xs tr td.#{$prefix}--table-expand {
