  tr.#{$prefix}--parent-row.#{$prefix}--data-table--selected.#{$prefix}--data-table--slug-row,
  .#{$prefix}--data-table--selected.#{$prefix}--data-table--slug-row,
  tr.#{$prefix}--data-table--selected.#{$prefix}--data-table--slug-row
