    .#{$prefix}--ai-label,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
    .#{$prefix}--list-box--invalid
    .#{$prefix}--ai-label,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
    .#{$prefix}--list-box--warning
    .#{$prefix}--ai-label,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
    .#{$prefix}--list-box--invalid
    .#{$prefix}--ai-label,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
    .#{$prefix}--list-box--warning
    .#{$prefix}--slug,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
