    > *,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
    .#{$prefix}--list-box--warning
    .#{$prefix}--list-box__field:has(
      .#{$prefix}--text-input:not(.#{$prefix}--text-input--empty)
    )
    ~ .#{$prefix}--ai-label,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
    .#{$prefix}--list-box--invalid
    .#{$prefix}--list-box__field:has(
      .#{$prefix}--text-input:not(.#{$prefix}--text-input--empty)
    )
    ~ .#{$prefix}--ai-label,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
    .#{$prefix}--list-box--warning
    .#{$prefix}--list-box__field:has(
      .#{$prefix}--text-input:not(.#{$prefix}--text-input--empty)
    )
    ~ .#{$prefix}--ai-label,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
    .#{$prefix}--list-box--invalid
    .#{$prefix}--list-box__field:has(
      .#{$prefix}--text-input:not(.#{$prefix}--text-input--empty)
    )
    ~ .#{$prefix}--ai-label,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
    .#{$prefix}--list-box--warning
    .#{$prefix}--list-box__field:has(
      .#{$prefix}--text-input:not(.#{$prefix}--text-input--empty)
    )
    ~ .#{$prefix}--slug,
  .#{$prefix}--list-box__wrapper--fluid.#{$prefix}--list-box__wrapper--slug
    .#{$prefix}--list-box--invalid
    .#{$prefix}--list-box__field:has(
