    .#{$prefix}--select-input__wrapper::before,
  .#{$prefix}--time-picker--fluid--warning
    .#{$prefix}--time-picker--fluid__wrapper
    > *:nth-child(2):not(:last-child)
    .#{$prefix}--select-input__wrapper::before,
  .#{$prefix}--time-picker--fluid--warning
    .#{$prefix}--time-picker--fluid__wrapper
    > *:last-child
    .#{$prefix}--select-input__wrapper::before {
    block-size: calc(100% - 1rem);
    inset-block-start: 8px;
