/// icon-indicator styles
/// @access public
/// @group tag
@mixin icon-indicator {
  .#{$prefix}--icon-indicator {
    @include type-style('body-compact-01');

    display: flex;
    align-items: center;
    color: $text-secondary;
    gap: $spacing-03;
    line-height: unset;
  }

  .#{$prefix}--icon-indicator svg {
    align-self: center;
  }

  .#{$prefix}--icon-indicator--20 {
    @include type-style('body-compact-02');

    line-height: unset;
  }

  .#{$prefix}--icon-indicator--failed {
    fill: $status-red;
  }

  .#{$prefix}--icon-indicator--caution-major {
    fill: $status-orange;

    path:first-of-type {
      fill: $black;
    }
  }

  .#{$prefix}--icon-indicator--caution-minor {
    fill: $status-yellow;

    path:first-of-type {
      fill: $black;
    }
  }

  .#{$prefix}--icon-indicator--undefined {
    fill: $status-purple;
  }

  .#{$prefix}--icon-indicator--succeeded {
    fill: $status-green;
  }

  .#{$prefix}--icon-indicator--normal {
    fill: $status-blue;
  }

  .#{$prefix}--icon-indicator--in-progress {
    fill: $status-blue;
  }

  .#{$prefix}--icon-indicator--incomplete {
    fill: $status-blue;
  }

  .#{$prefix}--icon-indicator--not-started {
    fill: $status-gray;
  }

  .#{$prefix}--icon-indicator--pending {
    fill: $status-gray;
  }

  .#{$prefix}--icon-indicator--unknown {
    fill: $status-gray;
  }

  .#{$prefix}--icon-indicator--informative {
    fill: $status-blue;
  }

  .#{$prefix}--icon-indicator__button {
    @include button-reset.reset($width: false);

    display: flex;

    &:focus {
      @include focus-outline.focus-outline;
    }
  }

  .#{$prefix}--icon-indicator .#{$prefix}--definition-tooltip {
    padding-block: $spacing-01;
  }
}

