  .#{$prefix}--popover--border.#{$prefix}--popover--left-bottom.#{$prefix}--popover--auto-align:dir(
      rtl
    )
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content
    > .#{$prefix}--popover-caret,
  .#{$prefix}--popover--border.#{$prefix}--popover--left-end.#{$prefix}--popover--auto-align:dir(
      rtl
    )
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content
    > .#{$prefix}--popover-caret {
    &::before {
      margin-inline-start: -1px;
    }

    &::after {
      inset-inline-start: 0;
    }
  }

  //-----------------------------------------------------------------------------
  // Tab Tip Variant
  //-----------------------------------------------------------------------------
  .#{$prefix}--popover--tab-tip
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content {
    @if not enabled('enable-v12-release') {
      border-radius: 0;
    }
  }

  .#{$prefix}--popover--tab-tip.#{$prefix}--popover--top-start:not(
      .#{$prefix}--popover--auto-align
    )
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content,
  .#{$prefix}--popover--tab-tip.#{$prefix}--popover--bottom-start:not(
      .#{$prefix}--popover--auto-align
    )
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content,
  .#{$prefix}--popover--tab-tip.#{$prefix}--popover--top-end:not(
      .#{$prefix}--popover--auto-align
    ):dir(rtl)
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content,
  .#{$prefix}--popover--tab-tip.#{$prefix}--popover--bottom-end:not(
      .#{$prefix}--popover--auto-align
    ):dir(rtl)
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content {
    inset-inline-start: 0;
  }

  .#{$prefix}--popover--tab-tip.#{$prefix}--popover--top-end:not(
      .#{$prefix}--popover--auto-align
    )
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content,
  .#{$prefix}--popover--tab-tip.#{$prefix}--popover--bottom-end:not(
      .#{$prefix}--popover--auto-align
    )
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content,
  .#{$prefix}--popover--tab-tip.#{$prefix}--popover--top-start:not(
      .#{$prefix}--popover--auto-align
    ):dir(rtl)
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content,
  .#{$prefix}--popover--tab-tip.#{$prefix}--popover--bottom-start:not(
      .#{$prefix}--popover--auto-align
    ):dir(rtl)
    > .#{$prefix}--popover
    > .#{$prefix}--popover-content {
    inset-inline-end: 0;
    inset-inline-start: initial;
  }

  .#{$prefix}--popover--tab-tip .#{$prefix}--popover {
    will-change: filter;
  }

  .#{$prefix}--popover--tab-tip__button {
    @include popover-tab-tip-button;
  }

  .#{$prefix}--popover--tab-tip.#{$prefix}--popover--open
    .#{$prefix}--popover--tab-tip__button {
    background: theme.$layer;
    box-shadow: 0 2px 2px rgb(0, 0, 0, 0.2);
  }

  .#{$prefix}--popover--tab-tip.#{$prefix}--popover--open
    .#{$prefix}--popover--tab-tip__button:not(:focus)::after {
    position: absolute;
    z-index: z('floating') + 1;
    background: theme.$layer;
    block-size: 2px;
    content: '';
    inline-size: 100%;
    inset-block-end: 0;
  }

  .#{$prefix}--popover--tab-tip__button svg {
    fill: theme.$icon-primary;
  }
}

