    position: relative;
    display: flex;
    align-items: center;
  }

  // Remove spacing above collection of radio buttons if label is present
  .#{$prefix}--label + .#{$prefix}--form-item .#{$prefix}--radio-button-group {
    margin-block-start: 0;
  }

  // vertical radio button
  .#{$prefix}--radio-button-group--vertical {
