  .#{$prefix}--tile--clickable:hover,
  .#{$prefix}--tile--clickable:active,
  .#{$prefix}--tile--clickable:visited,
  .#{$prefix}--tile--clickable:visited:hover {
    color: $text-primary;
    text-decoration: none;
