      enabled('enable-v12-tile-radio-icons') or
        $enable-experimental-tile-contrast or
        $enable-tile-contrast
    ) {
      opacity: 1;
    } @else {
      opacity: 0;
    }

    svg {
      border-radius: 50%;
      fill: $icon-secondary;
    }

    &:focus {
      @include focus-outline('outline');
    }
  }

  .#{$prefix}--tile__checkmark--persistent {
    opacity: 1;
  }

  .#{$prefix}--tile__chevron {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    block-size: $-icon-container-size;
    inline-size: $-icon-container-size;
    inset-block-end: 0;
    inset-inline-end: 0;

    svg {
      fill: $icon-primary;
      transform-origin: center;
      transition: $duration-fast-02 motion(standard, productive);

      @media screen and (prefers-reduced-motion: reduce) {
        transition: none;
      }
    }
  }

  .#{$prefix}--tile__chevron--interactive {
    @include button-reset.reset;

    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    block-size: $-icon-container-size;
    inline-size: $-icon-container-size;
    inset-block-end: 0;
    inset-inline-end: 0;
    @if (
      enabled('enable-experimental-tile-contrast') or
        $enable-experimental-tile-contrast or
        enabled('enable-tile-contrast') or
        $enable-tile-contrast
    ) {
      border: 1px solid $border-disabled;
    }

    &:focus {
      outline: 2px solid $focus;
      outline-offset: -2px;
    }

    &:hover {
      background-color: $layer-hover;
      cursor: pointer;
    }
  }

  .#{$prefix}--tile--expandable {
    position: relative;
    overflow: hidden;
    border: 0;
    color: inherit;
    cursor: pointer;
    font-family: inherit;
    font-size: inherit;
    inline-size: 100%;
    text-align: start;
    transition: max-height $duration-moderate-01 motion(standard, productive);

    @include type-style('body-compact-01');

    @if (
      enabled('enable-experimental-tile-contrast') or
        $enable-experimental-tile-contrast or
        enabled('enable-tile-contrast') or
        $enable-tile-contrast
    ) {
      border: 1px solid $border-tile;
    }

    &:hover {
      background: $layer-hover;
