@function to-rem($px) {
  @if math.unit($px) != 'px' {
    @error "Expected argument $px to be of type `px`, instead received: `#{math.unit($px)}`";
  }

  @return math.div($px, $base-font-size) * 1rem;
}

/// This function causes an error when using sass > 1.65.0
/// Replaced with `to-rem` function
