/// Skeleton loading animation
///
/// Pass `$border-radius` to round the skeleton. The radius is applied only
/// when `enable-v12-release` is on, so existing call sites stay square until
/// they opt in with a token such as `$border-radius-04`.
///
/// @param {Length | null} $border-radius [null] - Corner radius token. `null`
/// leaves radius unset. `0` / `$border-radius-00` are valid square values.
/// @access public
/// @example @include skeleton;
/// @example @include skeleton($border-radius: $border-radius-04);
/// @group utilities
@mixin skeleton($border-radius: null) {
  position: relative;
  padding: 0;
  border: none;
  background: $skeleton-background;
  box-shadow: none;
  pointer-events: none;

  // 0 / 0px are valid radius tokens but are falsy in Sass, so `!= null` is
  // required to distinguish "unset" from "square".
  // stylelint-disable scss/at-if-no-null
  @if enabled('enable-v12-release') {
    @if $border-radius != null {
      overflow: hidden;
      border-radius: $border-radius;
    }
  }

  // stylelint-enable scss/at-if-no-null
  &:hover,
  &:focus,
  &:active {
    border: none;
    cursor: default;
    outline: none;
  }

  &::before {
    position: absolute;
    animation: 3000ms ease-in-out #{$prefix}--skeleton infinite;
    background: $skeleton-element;
    block-size: 100%;
    content: '';
    inline-size: 100%;
    inset-inline-start: 0;
    will-change: transform-origin, transform, opacity;

    @media (prefers-reduced-motion: reduce) {
      animation: none;
    }
  }

  // High Contrast Mode support
  @include high-contrast-mode {
    background: CanvasText;

    &::before {
      background: Canvas;
      forced-color-adjust: none;
    }
  }
}

/// Circular Skeleton loading animation
/// @access public
/// @example @include circular-skeleton;
/// @group utilities
@mixin circular-skeleton {
  position: relative;
  overflow: hidden;
  border-radius: 50%;
  background: $skeleton-background;

  &::before {
    position: absolute;
    animation: 3000ms ease-in-out #{$prefix}--skeleton infinite;
    background: $skeleton-element;
    block-size: 100%;
    content: '';
    inline-size: 200%;
    will-change: transform-origin, transform, opacity;

    @media (prefers-reduced-motion: reduce) {
      animation: none;
    }
  }

  //High Contrast Mode
  //Ensure Skeleton is visible and animated in Windows HCM
  @include high-contrast-mode {
    background: CanvasText;

    &::before {
      background: Canvas;
      forced-color-adjust: none;
    }
  }
}

