    FILE_BANNER +
    '\n' +
    SCSS_IMPORTS +
    '\n' +
    `$${themeName}: (\n${entries}\n) !default;\n` +
    `$${themeName}: utilities.merge(\n` +
    `  $${themeName},\n` +
    `  layout.$spacing,\n` +
    `  layout.$fluid-spacing,\n` +
    `  type.$tokens\n` +
    `);\n`
  );
}

