@use 'sass:map';
@use 'font-family' as *;
@use 'prefix' as *;
@use 'styles' as *;

/// Create type classes for font families, weights, styles
/// @access public
/// @group @carbon/type
@mixin type-classes {
  // Font families
  @each $name, $value in $font-families {
    .#{$prefix}--type-#{$name} {
      font-family: $value;
    }
  }

  // Font weights
  @each $name, $value in $font-weights {
    .#{$prefix}--type-#{$name} {
      font-weight: $value;
    }
  }

  // Font styles
  .#{$prefix}--type-italic {
    font-style: italic;
  }

  // Type styles
  @each $name, $value in $tokens {
    .#{$prefix}--type-#{$name} {
      @include type-style($name, map.has-key($value, breakpoints));
    }
  }
}

