@use '../button/button';
@use '@carbon/styles/scss/components/action-set' as action-set-styles;

// Emit global .cds--action-set class rules (includes justify-content: flex-end)
@include action-set-styles.action-set;

$block-class: #{$prefix}--action-set;

// Mixin for button separator styles
@mixin button-separator($direction: horizontal) {
  $shadow: if(
    $direction == horizontal,
    to-rem(-1px) 0 0 0 button-tokens.$button-separator,
    0 to-rem(-1px) 0 0 button-tokens.$button-separator
  );

  // Slotted buttons
  ::slotted(#{$prefix}-button:not(:first-of-type)) {
    z-index: 1;
    box-shadow: $shadow;
  }

  ::slotted(#{$prefix}-button:focus-within),
  ::slotted(#{$prefix}-button:not(:first-of-type)[hide-margin]) {
    box-shadow: inherit;
  }

  // Directly rendered buttons (from actions prop)
  #{$prefix}-button:not(:first-of-type) {
    z-index: 1;
    box-shadow: $shadow;
  }

  #{$prefix}-button:focus-within,
  #{$prefix}-button:not(:first-of-type)[hide-margin] {
    box-shadow: inherit;
  }
}

:host(#{$prefix}-action-set) {
  // Override padding-inline-start for ghost buttons from ActionSet styles
  .#{$block-class}__action-button--ghost {
    /* stylelint-disable-next-line declaration-no-important */
    padding-inline-start: 0 !important;
  }

  // Button separator styles for horizontal layout
  @include button-separator(horizontal);

  @if flags.enabled('enable-v12-release') {
    @include button-radius.radius($border-radius-00);
  }
}

// Stacked layout styles
:host(#{$prefix}-action-set[stacked]) {
  @include button-separator(vertical);
}

// Side-panel specific overrides for button widths
:host(#{$prefix}-action-set[actions-multiple='single']) {
  // Single button should be full width
  ::slotted(#{$prefix}-button),
  #{$prefix}-button {
    flex: 0 0 100%;
    max-inline-size: none;
  }
}

:host(#{$prefix}-action-set[actions-multiple='double']) {
  // Double buttons should be 50% width each
  ::slotted(#{$prefix}-button),
  #{$prefix}-button {
    flex: 0 1 50%;
    max-inline-size: none;
  }
}

:host(#{$prefix}-action-set[actions-multiple='triple']) {
  // Triple buttons should be ~33% width each
  ::slotted(#{$prefix}-button),
  #{$prefix}-button {
    flex: 0 1 33.33%;
    max-inline-size: none;
  }
}

