$css--plex: true !default;

@use '@carbon/styles/scss/config' as *;
@use '@carbon/styles/scss/theme' as *;
@use '@carbon/styles/scss/spacing' as *;
@use '@carbon/styles/scss/type';
@use '@carbon/styles/scss/motion' as *;

$block-class: #{$prefix}--add-select__next;

:host(#{$prefix}-add-select-selection-summary-item) {
  display: block;

  // ── Wrapper ─────────────────────────────────────────────────────────────────
  .#{$block-class}__selection-summary-item {
    position: relative;
    background-color: $layer-01;
    border-block-end: 1px solid $border-subtle-01;

    &:hover {
      // Elevate above sibling items so the remove-button tooltip (which paints
      // within this shadow layer) renders on top of adjacent rows.
      z-index: 1;
      background-color: $layer-hover-01;
    }
  }

  // ── Accordion variant (custom — avoids shadow-boundary slot problems) ─────────

  .#{$block-class}__selection-summary-item-accordion {
    // No extra borders — wrapper owns the border-block-end
  }

  // Row that places the <button> and the remove button side-by-side.
  // position:relative here so the absolutely-positioned remove button is
  // anchored to this row rather than to the full-width <button>.
  .#{$block-class}__selection-summary-item-accordion-heading-row {
    position: relative;
    display: flex;
    align-items: center;
  }

  .#{$block-class}__selection-summary-item-accordion-heading {
    display: flex;
    flex: 1;
    align-items: center;
    appearance: none;
    border: none; /* stylelint-disable-line order/properties-order */
    background: none;
    color: $text-primary;
    cursor: pointer;
    // flex:1 makes the button fill the row; the remove button sits next to it.
    min-inline-size: 0;
    padding-block: $spacing-04;
    padding-inline: $spacing-05;

    &:hover {
      background-color: $layer-hover-01;
    }

    &:focus {
      outline: 2px solid $focus;
      outline-offset: -2px;
    }

    &:focus:not(:focus-visible) {
      outline: none;
    }
  }

  .#{$block-class}__selection-summary-item-accordion-arrow {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    margin-inline-end: $spacing-03;
    margin-inline-start: 0;
    transform: rotate(90deg);
    transition: transform $duration-fast-01 motion(standard, productive);

    @media screen and (prefers-reduced-motion: reduce) {
      transition: none;
    }

    svg {
      fill: $icon-primary;
    }

    &--open {
      transform: rotate(-90deg);
    }
  }

  .#{$block-class}__selection-summary-item-accordion-title {
    @include type.type-style('body-compact-01');

    display: block;
    flex: 1;
    padding-inline-end: $spacing-07;
    text-align: start;

    // When wrapping slotted content, act as a flex container
    &--slot {
      display: flex;
      align-items: flex-start;
    }
  }

  .#{$block-class}__selection-summary-item-accordion-body {
    padding-block: $spacing-05;
    padding-inline: $spacing-05;
  }

  // ── Non-accordion (default) variant ─────────────────────────────────────────
  .#{$block-class}__selection-summary-item--default {
    .#{$block-class}__selection-summary-item-title-wrapper {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding-block: $spacing-04;
      padding-inline: $spacing-05;
    }

    .#{$block-class}__selection-summary-item-content {
      padding-block-end: $spacing-04;
      padding-inline: $spacing-05;
    }

    .#{$block-class}__selection-summary-item-title {
      @include type.type-style('heading-compact-01');
    }
  }

  // ── Shared item sub-elements ─────────────────────────────────────────────────
  .#{$block-class}__selection-summary-item-title-wrapper {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .#{$block-class}__selection-summary-item-selected-item {
    display: flex;
    flex: 1;
    flex-direction: column;
  }

  .#{$block-class}__selection-summary-item-title {
    @include type.type-style('body-compact-01');

    margin: 0;
    color: $text-primary;
  }

  .#{$block-class}__selection-summary-item-subtitle {
    @include type.type-style('body-01');

    margin: 0;
    color: $text-secondary;
  }

  .#{$block-class}__selection-summary-item-content {
    margin-block-start: 0;
  }

  .#{$block-class}__selection-summary-item-entry {
    margin-block-end: $spacing-05;
  }

  .#{$block-class}__selection-summary-item-header {
    @include type.type-style('label-01');

    margin: 0;
    color: $text-secondary;
    margin-block-end: $spacing-03;
  }

  .#{$block-class}__selection-summary-item-body {
    @include type.type-style('body-01');

    margin: 0;
    margin-block-end: $spacing-05;
  }

  // ── Remove button ────────────────────────────────────────────────────────────

  // render-item wrapper — position:relative anchors the absolute remove button
  .#{$block-class}__selection-summary-item-render-item-wrapper {
    position: relative;
  }

  // Default (non-accordion) — inline at the right of the title row.
  .#{$block-class}__selection-summary-item-remove-button-container {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding-inline-start: $spacing-03;
  }

  // Accordion heading row and render-item — absolutely positioned, vertically centred.
  // Note: the selector targets the heading-row wrapper (not the <button> itself)
  // because the remove button is a sibling of the <button>, not a descendant.
  .#{$block-class}__selection-summary-item-accordion-heading-row
    .#{$block-class}__selection-summary-item-remove-button-container,
  .#{$block-class}__selection-summary-item-render-item-wrapper
    .#{$block-class}__selection-summary-item-remove-button-container {
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: $spacing-05;
    padding-inline-start: 0;
    // Use the standalone `translate` property instead of `transform: translateY()`
    // so this element does not become a containing block for position:fixed
    // descendants (tooltip popovers from the remove cds-icon-button).
    translate: 0 -50%;
  }

  // Remove button is hidden until hover/focus
  .#{$block-class}__selection-summary-item-remove-button {
    opacity: 0;
    transition: opacity $duration-fast-01 motion(standard, productive);

    @media screen and (prefers-reduced-motion: reduce) {
      transition: none;
    }
  }

  .#{$block-class}__selection-summary-item:hover
    .#{$block-class}__selection-summary-item-remove-button,
  .#{$block-class}__selection-summary-item:focus-within
    .#{$block-class}__selection-summary-item-remove-button {
    opacity: 1;
  }
}

