    margin-inline-start: $spacing-02;
  }
}

:host(#{$prefix}-breadcrumb-overflow-menu) {
  position: relative;
  block-size: rem(18px);
  inline-size: rem(20px);

  &:focus {
    outline: 1px solid $focus;
  }

  &:hover {
    background: transparent;

    ::after {
      opacity: 1;
    }
  }

  // Used to mimic link underline
  ::after {
    position: absolute;
    background: $link-primary-hover;
    block-size: 1px;
