:host(#{$prefix}-combo-box-item[disabled]) {
  cursor: not-allowed;

  .#{$prefix}--list-box__menu-item__option {
    color: $text-disabled;
    cursor: not-allowed;
    pointer-events: none;
    text-decoration: none;
  }
}

:host(#{$prefix}-combo-box-item[disabled][highlighted-next-sibling]:hover),
:host(#{$prefix}-combo-box-item[disabled][hovered-next-sibling]:hover)
  .#{$prefix}--list-box__menu-item__option {
  border-block-start-color: $border-subtle;
}

:host(#{$prefix}-combo-box-item[disabled]:hover)
  .#{$prefix}--list-box__menu-item__option {
  border-block-start-color: $border-subtle-01;
}

:host(#{$prefix}-combo-box-item[highlighted]) {
  @extend .#{$prefix}--list-box__menu-item--highlighted;
}

:host(#{$prefix}-combo-box-item[selected]) {
  @extend .#{$prefix}--list-box__menu-item--active;

  .#{$prefix}--list-box__menu-item__option {
    border-block-start-color: transparent;
    color: $text-primary;
  }

  .#{$prefix}--list-box__menu-item__selected-icon {
    display: block;
  }
}

:host(#{$prefix}-combo-box-item[selected-next-sibling])
  .#{$prefix}--list-box__menu-item__option {
  border-block-start-color: transparent;
}

:host(#{$prefix}-combo-box-item[disabled][selected-next-sibling]:hover)
  .#{$prefix}--list-box__menu-item__option {
  border-block-start-color: $border-subtle;
}

:host(#{$prefix}-combo-box-item[size='sm']) {
  block-size: $spacing-07;

  .#{$prefix}--list-box__menu-item__option {
    padding-block: to-rem(7px);
  }
}

:host(#{$prefix}-combo-box-item[size='lg']) {
  block-size: $spacing-09;

  .#{$prefix}--list-box__menu-item__option {
    padding-block: to-rem(15px);
  }
}

:host(#{$prefix}-combo-box[size='sm']) {
  .#{$prefix}--list-box__menu-icon {
    inset-block: $spacing-02;
  }
}

:host(#{$prefix}-combo-box[size='lg']) {
  .#{$prefix}--list-box__menu-icon {
    inset-block: $spacing-04;
  }
}

:host(#{$prefix}-combo-box[ai-label]) {
  @extend .#{$prefix}--list-box__wrapper--slug;

  .#{$prefix}--list-box__wrapper--decorator {
    @include ai-gradient;

    @if flags.enabled('enable-v12-release') {
      // Reset the bottom-edge color override from @include ai-gradient so the
      // border-box gradient layer controls all four sides uniformly.
      background:
        linear-gradient(
            0deg,
            $ai-aura-start-sm 0%,
            15%,
            $ai-aura-end 50%,
            transparent 100%
          )
          padding-box,
        linear-gradient($field, $field) padding-box,
        // (ai-border-start → ai-border-end), mirroring the default v12 border gradient
        linear-gradient(
            to bottom,
            $ai-border-start calc(100% - 4px),
            $ai-border-strong 100%
          )
          border-box;
      border-block-end-color: transparent;
    }
  }

  .#{$prefix}--list-box__field {
    padding: 0;
  }

  .#{$prefix}--list-box__invalid-icon {
    /* stylelint-disable-next-line declaration-no-important */
    inset-inline-end: to-rem(83px) !important;
  }

  ::slotted(#{$prefix}-ai-label)::after,
  ::slotted(#{$prefix}-slug)::after {
    position: absolute;
    display: block;
    background-color: $border-subtle-01;
    block-size: $spacing-05;
    content: '';
    inline-size: to-rem(1px);
    inset-block-start: 0;
    inset-inline-end: to-rem(-9px);
  }

  ::slotted(#{$prefix}-ai-label),
  ::slotted(#{$prefix}-slug) {
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: calc($spacing-08 + 9px);
  }

  ::slotted(#{$prefix}-ai-label:not([revert-active])),
  ::slotted(#{$prefix}-slug:not([revert-active])) {
    transform: translateY(-50%);
  }
}

:host(#{$prefix}-combo-box[ai-label][isClosable]) {
  ::slotted(#{$prefix}-ai-label),
  ::slotted(#{$prefix}-slug) {
    inset-inline-end: calc($spacing-10 + 18px);
  }

  .#{$prefix}--list-box__field .#{$prefix}--text-input {
    padding-inline-end: to-rem(105px);
  }
}

:host(#{$prefix}-combo-box[warn]),
:host(#{$prefix}-combo-box[invalid]) {
  ::slotted(#{$prefix}-ai-label),
  ::slotted(#{$prefix}-slug) {
    inset-inline-end: calc($spacing-08 + 9px);
  }

  ::slotted(#{$prefix}-ai-label)::before,
  ::slotted(#{$prefix}-slug)::before {
    position: absolute;
    display: block;
    background-color: $border-subtle-01;
    block-size: $spacing-05;
    content: '';
    inline-size: to-rem(1px);
    inset-block-start: 0;
    inset-inline-start: to-rem(-9px);
  }
}

:host(#{$prefix}-combo-box[warn][isClosable]:not([ai-label])),
:host(#{$prefix}-combo-box[invalid][isClosable]:not([ai-label])) {
  .#{$prefix}--list-box__field:has(.#{$prefix}--list-box__menu-icon)
    .#{$prefix}--list-box__selection::before {
    position: absolute;
    background-color: $border-subtle-01;
    block-size: to-rem(16px);
    content: '';
    inline-size: to-rem(1px);
    margin-inline-end: to-rem(33px);
  }
}

:host(#{$prefix}-combo-box[isClosable]) {
  .#{$prefix}--list-box__invalid-icon {
    /* stylelint-disable-next-line declaration-no-important */
    inset-inline-end: calc($spacing-10 + 18px) !important;
  }

  .#{$prefix}--list-box__field .#{$prefix}--text-input {
    padding-inline-end: to-rem(80px);
  }
}

:host(#{$prefix}-combo-box[warn][isClosable]),
:host(#{$prefix}-combo-box[invalid][isClosable]) {
  .#{$prefix}--list-box__field .#{$prefix}--text-input {
    padding-inline-end: to-rem(105px);
  }
}

:host(#{$prefix}-combo-box[warn][ai-label][isClosable]),
:host(#{$prefix}-combo-box[invalid][ai-label][isClosable]) {
  .#{$prefix}--list-box__field .#{$prefix}--text-input {
    padding-inline-end: to-rem(141px);
  }

  .#{$prefix}--list-box__invalid-icon {
    /* stylelint-disable-next-line declaration-no-important */
    inset-inline-end: to-rem(116px) !important;
  }
}

@include emit-layout-tokens-to-shadow-host('#{$prefix}-combo-box');

