:host(#{$prefix}-content-switcher-item[low-contrast][hide-divider])
  .#{$prefix}--content-switcher-btn::before {
  background-color: transparent;
}

:host(#{$prefix}-content-switcher-item[low-contrast]:first-of-type)
  .#{$prefix}--content-switcher-btn:not([disabled]) {
  box-shadow: inset rem(1px) 0 0 0 $border-strong;
}

:host(#{$prefix}-content-switcher-item[low-contrast]:last-of-type)
  .#{$prefix}--content-switcher-btn:not([disabled]) {
  box-shadow: inset rem(-1px) 0 0 0 $border-strong;
}

:host(#{$prefix}-content-switcher-item[icon][low-contrast]) ::slotted(svg) {
  fill: $icon-secondary;
}

@media (any-hover: hover) {
  :host(#{$prefix}-content-switcher-item[icon][low-contrast]:hover)
