    fill: $icon-primary;
  }
}

:host(#{$prefix}-content-switcher-item[icon][low-contrast][selected])
  ::slotted(svg) {
  fill: $icon-primary;
}

:host(#{$prefix}-content-switcher-item[icon][low-contrast][disabled])
  ::slotted(svg) {
  fill: $icon-disabled;
}

:host(#{$prefix}-content-switcher-item[icon][low-contrast][selected][disabled])
  ::slotted(svg) {
  fill: $icon-disabled;
}

