import { LitElement, html, nothing } from 'lit';
import { property, query } from 'lit/decorators.js';
import { prefix } from '../../globals/settings';
import styles from './data-table.scss?lit';
import { carbonElement as customElement } from '../../globals/decorators/carbon-element';

/**
 * Table batch actions.
 *
 * @element cds-table-batch-actions
 * @fires cds-table-batch-actions-cancel-clicked - The custom event fired after the Cancel button is clicked.
 * @fires cds-table-batch-actions-select-all-clicked - The custom event fired after the Select all button is clicked.
 */

@customElement(`${prefix}-table-batch-actions`)
class CDSTableBatchActions extends LitElement {
  /**
   * The slot element
   */
  @query('slot')
  private _slotElement?: HTMLSlotElement;

  /**
   * The cancel button element
   */
  @query(`${prefix}-button.${prefix}--batch-summary__cancel`)
  private _cancelButton?: HTMLElement;

  /**
   * Handles `click` event on the Cancel button.
   */
  private _handleCancel() {
    const { eventClickCancel } = this
      .constructor as typeof CDSTableBatchActions;
    this.dispatchEvent(
      new CustomEvent(eventClickCancel, { bubbles: true, composed: true })
    );
  }

  /**
   * Handles `click` event on the Select all button.
   */
  private _handleSelectAll() {
    this.dispatchEvent(
      new CustomEvent(CDSTableBatchActions.eventClickSelectAll, {
        bubbles: true,
        composed: true,
      })
    );
  }

  /**
   * `true` if this batch actions bar should be active.
   */
  @property({ type: Boolean, reflect: true })
  active = false;

  /**
   * The formatter for selected items. Should be changed upon the locale the UI is rendered with.
   */
  @property({ attribute: false })
  formatSelectedItemsCount = ({ count }) =>
    `${count} item${count <= 1 ? '' : 's'} selected`;

  /**
   * Numeric representation of the total number of items selected in a table.
   * This number is used to derive the selection message.
   */
  @property({ type: Number, attribute: 'selected-rows-count' })
  selectedRowsCount = 0;

  /**
   * Numeric representation of the total number of items in a table.
   * This number is used in the select all button text
   * This property controls the rendering of the Select all button
   */
  @property({ type: Number, attribute: 'total-rows-count' })
  totalRowsCount = 0;

  /**
   * The table size.
   */
  @property({ reflect: true })
  size = 'lg';

  firstUpdated() {
    this._updateButtons();
    this._setupHoverListeners();
  }

  private _setupHoverListeners() {
    if (this._slotElement && this._cancelButton) {
      const setupListeners = () => {
        const buttons = this._slotElement?.assignedElements();
        if (!buttons) return;

        const lastButton = buttons[buttons.length - 1] as HTMLElement;

        if (lastButton) {
          const handleEnter = () => {
            this._cancelButton?.style.setProperty('--divider-opacity', '0');
          };

          const handleLeave = () => {
            this._cancelButton?.style.setProperty('--divider-opacity', '1');
          };

          lastButton.removeEventListener('mouseenter', handleEnter);
          lastButton.removeEventListener('mouseleave', handleLeave);

          lastButton.addEventListener('mouseenter', handleEnter);
          lastButton.addEventListener('mouseleave', handleLeave);
        }
      };

      setupListeners();
      this._slotElement.addEventListener('slotchange', setupListeners);
    }
  }

  updated(changedProperties) {
    if (changedProperties.has('active')) {
      this.setAttribute('tabindex', `${this.active ? '' : '-1'}`);
    }

    if (changedProperties.has('size')) {
      this._updateButtons();
    }
  }

  private _updateButtons() {
    this.querySelectorAll(
      (this.constructor as typeof CDSTableBatchActions).selectorButtons
    ).forEach((button) => {
      button.setAttribute('batch-action', '');
      button.setAttribute('size', this.size);
    });
  }

  render() {
    const {
      formatSelectedItemsCount,
      selectedRowsCount,
      totalRowsCount,
      _handleCancel: handleCancel,
      _handleSelectAll: handleSelectAll,
      size,
    } = this;

    return html`
      <div class="${prefix}--batch-summary">
        <p class="${prefix}--batch-summary__para">
          ${formatSelectedItemsCount({ count: selectedRowsCount })}
        </p>
        ${totalRowsCount > 0
          ? html`
              <span class="${prefix}--batch-summary__divider">|</span>
              <button
                class="${prefix}--btn ${prefix}--btn--primary ${prefix}--batch-summary__select-all"
                @click=${handleSelectAll}>
                <slot name="select-all-button-content"
                  >Select all (${totalRowsCount})</slot
                >
              </button>
            `
          : nothing}
      </div>

      <div class="${prefix}--action-list">
        <slot></slot>
        <cds-button
          kind="primary"
          size="${size}"
          class="${prefix}--batch-summary__cancel"
          batch-action
          @click=${handleCancel}>
          <slot name="cancel-button-content">Cancel</slot>
        </cds-button>
      </div>
    `;
  }

  /**
   * The CSS selector to find the action buttons.
   */
  static get selectorButtons() {
    return `${prefix}-button`;
  }

  /**
   * The name of the custom event fired after the Cancel button is clicked.
   */
  static get eventClickCancel() {
    return `${prefix}-table-batch-actions-cancel-clicked`;
  }

  /**
   * The name of the custom event fired after the Select all button is clicked.
   */
  static get eventClickSelectAll() {
    return `${prefix}-table-batch-actions-select-all-clicked`;
  }

  static styles = styles;
}

export default CDSTableBatchActions;

