:host(#{$prefix}-date-picker-input) {
  .#{$prefix}--date-picker__icon {
    @extend .#{$prefix}--date-picker__icon;
  }

  .#{$prefix}--date-picker__icon--warn {
    @extend .#{$prefix}--date-picker__icon--warn;
  }

  .#{$prefix}--date-picker__icon--invalid {
    @extend .#{$prefix}--date-picker__icon--invalid;
  }

  ::slotted(#{$prefix}-ai-label),
  ::slotted(#{$prefix}-slug) {
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: $spacing-08;
  }

  ::slotted(#{$prefix}-ai-label:not([revert-active])),
  ::slotted(#{$prefix}-slug:not([revert-active])) {
    transform: translateY(-50%);
  }
}

:host(#{$prefix}-date-picker-input-skeleton) {
  @if flags.enabled('enable-v12-release') {
    display: inline-flex;
    flex-direction: row;
  } @else {
    display: inline-block;
  }

  .#{$prefix}--label {
    @include skeleton($border-radius: $border-radius-04);

    block-size: rem(14px);

    inline-size: rem(75px);
  }

  .#{$prefix}--date-picker-input-skeleton-container {
    display: inline-block;
  }
}

:host(#{$prefix}-date-picker-input-skeleton[range]) {
  .#{$prefix}--date-picker-input-skeleton-container {
    inline-size: rem(143.5px);

    .#{$prefix}--date-picker__input {
      inline-size: rem(143.5px);
    }
  }

  @if flags.enabled('enable-v12-release') {
    column-gap: rem(1px);

    .#{$prefix}--date-picker-input-skeleton-container:first-of-type
      .#{$prefix}--date-picker__input {
      border-end-end-radius: $border-radius-00;
      border-start-end-radius: $border-radius-00;
    }

    .#{$prefix}--date-picker-input-skeleton-container:last-of-type
      .#{$prefix}--date-picker__input {
      border-end-start-radius: $border-radius-00;
      border-start-start-radius: $border-radius-00;
    }
  }
}

:host(#{$prefix}-date-picker-input[ai-label])
  .#{$prefix}--date-picker__input--decorator {
  @include ai-gradient;

  @if flags.enabled('enable-v12-release') {
    // Reset the bottom-edge color override from @include ai-gradient so the
    // border-box gradient layer controls all four sides uniformly.
    background:
      linear-gradient(
          0deg,
          $ai-aura-start-sm 0%,
          15%,
          $ai-aura-end 50%,
          transparent 100%
        )
        padding-box,
      linear-gradient($field, $field) padding-box,
      // (ai-border-start → ai-border-end), mirroring the default v12 border gradient
      linear-gradient(
          to bottom,
          $ai-border-start calc(100% - 4px),
          $ai-border-strong 100%
        )
        border-box;
    border-block-end-color: transparent;
  }
}

.#{$prefix}--form-requirement {
  box-sizing: border-box;
  inline-size: 0;
  min-inline-size: 100%;
}

