:host(#{$prefix}-fluid-date-picker[invalid]) {
  @extend .#{$prefix}--date-picker--fluid--invalid;
}

:host(#{$prefix}-fluid-date-picker[warn]:not([invalid])) {
  @extend .#{$prefix}--date-picker--fluid--warn;
}

:host(#{$prefix}-fluid-date-picker[readonly]),
:host(#{$prefix}-fluid-date-picker[data-input-readonly]) {
  @if not flags.enabled('enable-v12-release') {
    @extend .#{$prefix}--date-picker--fluid--readonly;
  }
}

// ── Fluid date picker input ──────────────────────────────────────────────────

:host(#{$prefix}-fluid-date-picker-input) {
  position: relative;
  display: block;
  box-sizing: border-box;
  background: $field;
  block-size: convert.to-rem(64px);
