                  placeholder="e.g. carbon-design-system"
                  size="${ifDefined(size)}"
                  ?disabled="${disabled}"
                  ?readonly="${readOnly}"
                  ?invalid="${invalid}"
                  invalid-text="${ifDefined(invalidText)}"
                  ?warn="${warn}"
                  warn-text="${ifDefined(warnText)}">
                  ${decorator()}
