                  helper-text="Start typing to find a team member."
                  placeholder="Search members..."
                  size="${ifDefined(listBoxSize)}"
                  ?disabled="${disabled}"
                  ?read-only="${readOnly}"
                  ?invalid="${invalid}"
                  invalid-text="${ifDefined(invalidText)}"
                  ?warn="${warn}"
