export const blockClass = `${prefix}--guidebanner`;
const blockEvent = `${prefix}-guidebanner`;

/**
 * GuideBanner.
 *
 * @element cds-guide-banner
 * @csspart guide-banner
 * @fires cds-guide-banner-toggle Custom event fired when banner is opened
 * @fires cds-guide-banner-close Custom event fired when banner is closed
 * */

@customElement(`${prefix}-guide-banner`)
class CDSGuideBanner extends HostListenerMixin(LitElement) {
  @property({ type: String, reflect: true, attribute: 'collapse-text' })
  collapseText!: string;

  @property({ type: String, reflect: true, attribute: 'expand-text' })
  expandText!: string;

  @property({ type: Boolean, reflect: true })
  open = false;

  @property({ type: String, reflect: true, attribute: 'title-text' })
  titleText!: string;

  static get eventToggle() {
    return `${blockEvent}-toggle`;
  }

  static get eventOnClose() {
    return `${blockEvent}-close`;
  }

  private _handleClose() {
    const init = {
      bubbles: true,
      composed: true,
      detail: {},
    };
    this.dispatchEvent(
      new CustomEvent(
        (this.constructor as typeof CDSGuideBanner).eventOnClose,
        init
      )
    );
  }

  _handleToggle() {
    this.open = !this.open;
    const init = {
      bubbles: true,
      composed: true,
      detail: {
        open: this.open,
      },
    };
    this.dispatchEvent(
      new CustomEvent(
        (this.constructor as typeof CDSGuideBanner).eventToggle,
        init
      )
    );
  }

  private _getTitle() {
    return html`<div class="${blockClass}__title">${this.titleText}</div>`;
  }

  private _getButton() {
    const buttonText = this.open ? this.collapseText : this.expandText;
    return html`<cds-button
      kind="ghost"
      size="md"
      class="${blockClass}__toggle-button"
      @click=${this._handleToggle}>
      ${buttonText}
    </cds-button>`;
  }

  render() {
    const classes = classMap({
      [`${blockClass}`]: true,
      [`${blockClass}__collapsible-collapsed`]: !this.open,
    });
    return html`
