const iconMap = {
  [ICON_INDICATOR_KIND.FAILED]: {
    16: ErrorFilled16,
    20: ErrorFilled20,
  },
  [ICON_INDICATOR_KIND['CAUTION-MAJOR']]: {
    16: WarningAltInvertedFilled16,
    20: WarningAltInvertedFilled20,
  },
  [ICON_INDICATOR_KIND['CAUTION-MINOR']]: {
    16: WarningAltFilled16,
    20: WarningAltFilled20,
  },
  [ICON_INDICATOR_KIND.UNDEFINED]: {
    16: UndefinedFilled16,
    20: UndefinedFilled20,
  },
  [ICON_INDICATOR_KIND.SUCCEEDED]: {
    16: CheckmarkFilled16,
    20: CheckmarkFilled20,
  },
  [ICON_INDICATOR_KIND.NORMAL]: {
    16: CheckmarkOutline16,
    20: CheckmarkOutline20,
  },
  [ICON_INDICATOR_KIND['IN-PROGRESS']]: {
    16: InProgress16,
    20: InProgress20,
  },
  [ICON_INDICATOR_KIND.INCOMPLETE]: {
    16: Incomplete16,
    20: Incomplete20,
  },
  [ICON_INDICATOR_KIND['NOT-STARTED']]: {
    16: CircleDash16,
    20: CircleDash20,
  },
  [ICON_INDICATOR_KIND.PENDING]: {
    16: PendingFilled16,
    20: PendingFilled20,
  },
  [ICON_INDICATOR_KIND.UNKNOWN]: {
    16: UnknownFilled16,
    20: UnknownFilled20,
  },
  [ICON_INDICATOR_KIND.INFORMATIVE]: {
    16: WarningSquareFilled16,
    20: WarningSquareFilled20,
  },
};

/**
 * Icon Indicator.
 *
 * @element cds-icon-indicator
 */
@customElement(`${prefix}-icon-indicator`)
class CDSIconIndicator extends LitElement {
  /**
   * Specify how the tooltip should align with the icon in compact mode
   */
  @property({ reflect: true })
  align: POPOVER_ALIGNMENT = POPOVER_ALIGNMENT.RIGHT;

  /**
   * Will auto-align the tooltip in compact mode
   */
  @property({ type: Boolean, reflect: false })
  autoalign = false;

  /**
   * When true, displays only the icon with the label in a tooltip
   */
  @property({ type: Boolean, reflect: true })
  compact = false;

  /**
   * Description for the icon announced to screen readers in compact mode.
   * Defaults to `label` when not provided.
   */
  @property({ attribute: 'icon-description' })
  iconDescription?: string;

  /**
   * Icon indicator should be size 16 or 20
   */
  @property()
  size = 16;

  /**
   * Label next to the icon.
   */
  @property()
  label!: string;

  /**
   * Icon Indicator kind
   */
  @property()
  kind!: ICON_INDICATOR_KIND;

  render() {
    const IconComponent = iconMap[this.kind]?.[this.size];
    const iconElement = iconLoader(IconComponent, { size: this.size });

    if (this.compact) {
      return html`
        <cds-definition-tooltip
          align=${this.align}
          ?autoalign=${this.autoalign}
          open-on-hover>
          ${iconElement}
          <span class="${prefix}--visually-hidden"
            >${this.iconDescription ?? this.label}</span
          >
          <span slot="definition">${this.label}</span>
        </cds-definition-tooltip>
      `;
    }

    return html`${iconElement}${this.label}`;
  }

  static styles = styles;
}

export default CDSIconIndicator;

