    this.selected = !this.selected;
    const init = {
      bubbles: true,
      cancelable: true,
      composed: true,
      detail: {
        triggeredBy: e.target,
      },
    };
    if (
      this.dispatchEvent(
        new CustomEvent(
          (this.constructor as typeof CDSmenuItemSelectable).eventOnChange,
          init
        )
      )
    ) {
