@use '@carbon/styles/scss/feature-flags' as flags;
@use '@carbon/styles/scss/utilities/convert';
@use './menu-variables' as *;

:host(#{$prefix}-menu) {
  position: fixed;
  z-index: z('modal');
  --grid-template: 1fr max-content;
  --display-icon-item: none;
  --display-selection-icon: none;
  --block-size-value: #{$spacing-07};

  &:not([open]) {
    pointer-events: none;
  }
}

.#{$prefix}--menu--with-icons {
  --grid-template: #{$spacing-05} 1fr max-content;
  --display-icon-item: flex;
}
.#{$prefix}--menu--with-selectable-items {
  --grid-template: #{$spacing-05} 1fr max-content;
  --display-selection-icon: flex;
}

.#{$prefix}--menu--with-icons.#{$prefix}--menu--with-selectable-items {
  --grid-template: #{$spacing-05} #{$spacing-05} 1fr max-content;
}

.#{$prefix}--menu {
  @extend .#{$prefix}--menu;

  opacity: 0;
  overflow-y: auto;
  pointer-events: none;
  visibility: hidden;

  &--shown {
    opacity: 1;
  }

  &--open {
    visibility: visible;

    &:focus {
      @include focus-outline('border');
    }
  }

  &--with-icons {
    min-inline-size: 12rem;
  }

  // Only allow interaction once the menu is both open and positioned.
  &--open.#{$prefix}--menu--shown {
    pointer-events: auto;
  }

  &--border {
    @extend .#{$prefix}--menu--border;
  }

  &--background-token__background {
    @extend .#{$prefix}--menu--background-token__background;
  }
}
.#{$prefix}--menu--with-icons {
  min-inline-size: 12rem;
}

.#{$prefix}--menu--xs {
  --block-size-value: 1.5rem;
}
.#{$prefix}--menu--sm {
  --block-size-value: 2rem;
}
.#{$prefix}--menu--md {
  --block-size-value: 2.5rem;
}
.#{$prefix}--menu--lg {
  --block-size-value: 3rem;
}

// A submenu is spaced away from its parent menu item, so the pointer has to cross a
// gap belonging to neither. This causes `mouseleave` to fire, closing the submenu prematurely
//
// This spans exactly that gap, stopping at the item's edge, so it covers only the
// space in between.
//
// Visually, everything looks the same, but functionally, the submenu stays open since
// the cursor technically never left it.
:host(#{$prefix}-menu[ischild]) .#{$prefix}--menu {
  &::before {
    position: absolute;
    content: '';
    cursor: auto;
    inline-size: $spacing-01;
    inset-block: 0;
    inset-inline-start: -$spacing-01;

    @if flags.enabled('enable-v12-release') {
      inline-size: convert.to-rem(6px);
      inset-inline-start: calc(-1 * convert.to-rem(6px));
    }
  }

  &--shown {
    overflow: visible;
  }
}

