:host(#{$prefix}-modal[open]) {
  @extend .#{$prefix}--modal;

  opacity: 1;
  transition:
    opacity $duration-moderate-02 motion(entrance, expressive),
    visibility 0ms linear;
  visibility: inherit;

  .#{$prefix}--modal-container {
    transform: translate3d(0, 0, 0);
    transition: transform $duration-moderate-02 motion(entrance, expressive);
  }

  @media screen and (prefers-reduced-motion: reduce) {
    transition: none;
  }
}

:host(#{$prefix}-modal) {
  @extend .#{$prefix}--modal;

  opacity: 0;
  transition:
    opacity $duration-moderate-02 motion(exit, expressive),
    visibility 0ms linear $duration-moderate-02;
  visibility: hidden;
}

:host(#{$prefix}-modal[full-width]) {
  ::slotted(#{$prefix}-modal-body) {
    padding: 0;
    margin: 0;
  }
}

:host(#{$prefix}-modal[has-scrolling-content]) ::slotted(#{$prefix}-modal-body),
:host(#{$prefix}-modal) ::slotted(#{$prefix}-modal-body[is-scrollable]) {
  @extend .#{$prefix}--modal-scroll-content;
}

:host(#{$prefix}-modal) ::slotted(#{$prefix}-modal-body[no-fade]) {
  @extend .#{$prefix}--modal-scroll-content--no-fade;
}

:host(#{$prefix}-modal-header) {
  @extend .#{$prefix}--modal-header;
}

:host(#{$prefix}-modal-close-button) {
  @extend .#{$prefix}--modal-close-button;

  outline: none;
}

:host(#{$prefix}-modal-close-button) #{$prefix}-icon-button::part(button) {
  border-width: 2px;
}

:host(#{$prefix}-modal-heading),
:host(#{$prefix}-modal-label) {
