 */
@customElement(`${prefix}-preview-multi-select`)
class CDSPreviewMultiSelect extends FormAssociatedMixin(CDSMultiSelect) {
  static get is() {
    return `${prefix}-preview-multi-select`;
  }
}

export default CDSPreviewMultiSelect;

