      } else {
        const filteredData = dataPrevious.filter(
          (obj) => obj.id !== notificationId
        );
        setDataPrevious([...filteredData]);
      }
    };
    const clickOutside = () => {
      setOpenPanel(false);
      const updatedTodayData = dataToday.map((data) => {
        return {
          ...data,
          unread: false,
        };
      });
      const updatedPreviousData = dataPrevious.map((data) => {
        return {
          ...data,
          unread: false,
        };
