                  </cds-notification>
                `;
              })}
            `
          : ''}
        ${dataPrevious.length > 0
          ? html`
              ${dataPrevious.map((item) => {
                return html`
                  <cds-notification
                    slot="previous"
                    @click=${item.onNotificationClick}
                    @cds-notification-dismiss=${() => {
