            ${subtitle}<slot name="subtitle"></slot>
          </div>`}
          <slot></slot>
        </div>
      </div>
    `;
  }

  protected _renderButton() {
    return html``;
  }

  connectedCallback() {
    super.connectedCallback();
    this.removeAttribute('role');
  }

