};

const argTypes = {
  caption: {
    control: 'text',
    description: 'Specify the caption.',
  },
  hideCloseButton: {
    control: 'boolean',
    description: 'Specify the close button should be disabled, or not.',
  },
  kind: {
    control: 'select',
