            label="With helper text"
            invalid-text="Value must be between 0 and 10000000"
            helper-text="This is helper text for the input"
            @cds-number-input="${onInput}">
          </cds-number-input>
        </cds-form-item>

        <!-- With AI Label -->
        <cds-form-item>
          <cds-number-input
            type="text"
            input-mode="decimal"
            value="50"
            min="0"
            max="10000000"
            step="1"
            label="With AI Label"
            invalid-text="Value must be between 0 and 10000000"
            helper-text="Has AI decorator"
            @cds-number-input="${onInput}">
            <cds-ai-label alignment="bottom-left">
              ${content}${actions}
            </cds-ai-label>
          </cds-number-input>
        </cds-form-item>
      </div>
    `;
  },
};

