:host(#{$prefix}-overflow-menu[data-programmatic-focus]),
:host(#{$prefix}-breadcrumb-overflow-menu[data-programmatic-focus]) {
  @include focus-outline('outline');
}

:host(#{$prefix}-overflow-menu),
:host(#{$prefix}-breadcrumb-overflow-menu) {
