  }
}

:host(#{$prefix}-overflow-menu[open]),
:host(#{$prefix}-breadcrumb-overflow-menu[open]) {
  background-color: $layer-01;
  box-shadow: 0 $spacing-01 6px 0 rgb(0, 0, 0, 0.3);
  transition: none;

