      outline: 1px solid $focus;
    }

    @media (any-hover: hover) {
      &:hover {
        &::after {
          background: $link-primary-hover;
        }
      }
    }

    &:active {
      &::after {
        background: $text-primary;
      }
    }

    &::after {
      position: absolute;
