export const Popover = {
  args: {
    caret: true,
    highContrast: false,
    align: popoverAlignments.bottom,
    dropShadow: true,
  },
  argTypes: {
    caret: {
      control: 'boolean',
      description: 'Caret (caret)',
    },
    highContrast: {
      control: 'boolean',
      description: 'High contrast (highContrast)',
    },
    align: {
      control: 'select',
      description: 'Align (align)',
      options: popoverAlignments,
    },
    dropShadow: {
      control: 'boolean',
      description: 'Drop shadow (dropShadow)',
    },
  },
  render: (args) => {
    const { caret, highContrast, align, dropShadow } = args ?? {};

    const handleClick = (id) => {
      const popover = document.querySelector(id);
      const open = popover?.hasAttribute('open');
      if (open) {
        popover?.removeAttribute('open');
      } else {
        popover?.setAttribute('open', '');
      }
    };

    return html`
      <style>
        ${styles}
      </style>
      <cds-popover
        autoalign
        id="popover-one"
        open
        ?caret=${caret}
        ?highContrast=${highContrast}
        align=${align}
        ?dropShadow=${dropShadow}>
        <button
          class="playground-trigger"
          aria-label="Settings"
          type="button"
          @click="${() => handleClick('#popover-one')}">
          ${iconLoader(Checkbox16)}
        </button>
        <cds-popover-content>
          <div class="p-3">
            <p class="popover-title">Available storage</p>
            <p class="popover-details">
              This server has 150 GB of block storage remaining.
            </p>
          </div>
        </cds-popover-content>
      </cds-popover>
    `;
  },
};

