export const Determinate = {
  args: {
    ...args,
    helperText: 'Fetching assets...',
    label: 'Exporting data',
    max: 728,
    status: PROGRESS_BAR_STATUS.ACTIVE,
    value: undefined,
  },
  argTypes: {
    ...argTypes,
