      </cds-select>
    </div>`;
  },
};

export const WithLayer = {
  decorators: [withLayers],
  parameters: {
    layout: 'fullscreen',
    controls: { exclude: ['onInput'] },
  },
  args: sharedArgs,
  argTypes: sharedArgTypes,
  render: (args) => {
    const {
      disabled,
      helperText,
      hideLabel,
      id,
      invalid,
      invalidText,
      labelStylesDisable,
      labelText,
      name,
      placeholder,
      size,
      readOnly,
      warn,
      warnText,
      value,
      onInput,
    } = args ?? {};

    return html`
      <cds-select
        id="${id}"
        ?inline="${false}"
        ?disabled="${disabled}"
        helper-text="${ifDefined(helperText)}"
        ?hide-label="${hideLabel}"
        ?invalid="${invalid}"
        invalid-text="${ifDefined(invalidText)}"
        ?label-styles-disable="${labelStylesDisable}"
        label-text="${ifDefined(labelText)}"
        name="${ifDefined(name)}"
        placeholder="${ifDefined(placeholder)}"
        size="${ifDefined(size)}"
        ?readonly="${readOnly}"
        ?warn="${warn}"
        warn-text="${ifDefined(warnText)}"
        value="${ifDefined(value)}"
        @cds-select-selected="${onInput}">
        ${selectItems}
      </cds-select>
    `;
  },
};

