  }

  .#{$prefix}-ce--slider__filled-track-container {
    transform: rotate(0) #{'/*rtl:rotate(180deg)*/'};
  }

  .#{$prefix}--slider > .#{$prefix}--slider__thumb {
    z-index: 3;
    block-size: 0.875rem;
    inline-size: 0.875rem;
