      _dragging: dragging,
      _trackNode: trackNode,
      _draggingUpper: draggingUpper,
    } = this;
    if (!disabled) {
      const isRtl =
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- https://github.com/carbon-design-system/carbon/issues/20452
        trackNode
          .ownerDocument!.defaultView!.getComputedStyle(trackNode)
          .getPropertyValue('direction') === 'rtl';
      const thumbPosition = event.clientX;
      const { left: trackLeft, width: trackWidth } =
        this._trackNode.getBoundingClientRect();
      if (dragging) {
        this._setThumbTooltipOpen(this._thumbNode, true);
        const position =
          (isRtl
            ? trackLeft + trackWidth - thumbPosition
            : thumbPosition - trackLeft) / trackWidth;
        if (
          !this.unstable_valueUpper ||
          position * 100 <= this.unstable_valueUpper
        ) {
          this._rate = position;
          this.dispatchEvent(
            new CustomEvent(
              (this.constructor as typeof CDSSlider).eventChange,
              {
                bubbles: true,
                composed: true,
                detail: {
                  value: this.value,
                  intermediate: true,
                },
              }
            )
          );
        }
      } else if (draggingUpper) {
        this._setThumbTooltipOpen(this._thumbNodeUpper, true);
        const position =
          (isRtl
            ? trackLeft + trackWidth - thumbPosition
            : thumbPosition - trackLeft) / trackWidth;
        if (position * 100 >= this.value) {
          this._rateUpper = position;
          this.dispatchEvent(
            new CustomEvent(
              (this.constructor as typeof CDSSlider).eventChange,
              {
                bubbles: true,
                composed: true,
                detail: {
                  value: this.unstable_valueUpper,
                  intermediate: true,
                },
              }
            )
          );
        }
      }
    }
  }

  /**
   * Handles `pointerup` and `pointerleave` event to finishing dragging.
   */
  private _endDrag = () => {
    const wasDragging = this._dragging;
    const wasDraggingUpper = this._draggingUpper;
    if (this._dragging || this._draggingUpper) {
      this.dragCoolDown = true;
    } else {
      this.dragCoolDown = false;
    }
    if (this._dragging) {
      this.dispatchEvent(
        new CustomEvent((this.constructor as typeof CDSSlider).eventChange, {
          bubbles: true,
          composed: true,
          detail: {
            value: this.value,
          },
        })
      );
      this._dragging = false;
      this._thumbNode.style.touchAction = '';
    } else if (this._draggingUpper) {
      this.dispatchEvent(
        new CustomEvent((this.constructor as typeof CDSSlider).eventChange, {
          bubbles: true,
          composed: true,
          detail: {
            value: this.unstable_valueUpper,
          },
        })
      );
      this._draggingUpper = false;
      this._thumbNodeUpper.style.touchAction = '';
    }
    if (wasDragging) {
      const shouldKeepOpen =
        this._thumbNode?.matches(':hover') ||
        this.shadowRoot?.activeElement === this._thumbNode;
      if (!shouldKeepOpen) {
        this._setThumbTooltipOpen(this._thumbNode, false);
      }
    } else if (wasDraggingUpper) {
      const shouldKeepOpen =
        this._thumbNodeUpper?.matches(':hover') ||
        this.shadowRoot?.activeElement === this._thumbNodeUpper;
      if (!shouldKeepOpen) {
        this._setThumbTooltipOpen(this._thumbNodeUpper, false);
      }
