      if (eventContainer === 'upper') {
        this.unstable_valueUpper = value;
      } else {
        this.value = value;
      }
    }
    const valueMain =
      eventContainer === 'upper' ? this.unstable_valueUpper : this.value;
    if (valueMain !== '') {
      this.dispatchEvent(
        new CustomEvent((this.constructor as typeof CDSSlider).eventChange, {
          bubbles: true,
          composed: true,
          detail: {
            value: valueMain,
            intermediate,
          },
        })
      );
    }
  };

