          : `translate(0%, -50%) scaleX(${this._rate})`;
      } else {
        this._sliderFilledTrack.style.transform = this.unstable_valueUpper
          ? `translate(${this._rate * 100}%, -50%) scaleX(${this._rateUpper - this._rate})`
