        }
      }
      if (changedProperties.has('invalid')) {
        input.invalid = this.invalid;
      }
      if (changedProperties.has('warn')) {
        input.warn = this.warn;
      }
      if (changedProperties.has('hideTextInput')) {
        input.hideTextInput = this.hideTextInput;
