@include emit-layout-context-classes();
@include emit-layout-context-classes('density');

$inset-transition: inset 110ms motion(standard, productive);

:host(#{$prefix}-tabs),
:host(#{$prefix}-tabs-skeleton) {
  @extend .#{$prefix}--tabs;
  @include emit-layout-tokens();

  .#{$prefix}--tabs-nav-content-container {
    position: relative;
    overflow: scroll;
    flex: 1 1 0%;
    // for some reason, overflow: hidden shrinks the content
    block-size: layout.size('height');
    scrollbar-width: none;

    &::-webkit-scrollbar {
      display: none;
    }
  }

  /* Set to zero-specificity so it can be overridden by dynamic stylesheet */
  :where(.#{$prefix}--tabs-nav-content) {
    position: absolute;
    block-size: 100%;
    inset-inline-start: 0;
    transition: $inset-transition;
  }

  .#{$prefix}--tabs-nav {
    position: absolute;
    display: block;
  }

  .#{$prefix}--tab--overflow-nav-button {
    z-index: 1;
  }

  .#{$prefix}--tab--overflow-nav-button {
    background-color: var(--tabs-overflow-button-background, $background);
  }

  .#{$prefix}--tab--overflow-nav-button--hidden {
    display: none;
  }
}

// RTL caret display
:host(#{$prefix}-tabs:dir(rtl)) .#{$prefix}--tab--overflow-nav-button svg {
  transform: scaleX(-1);
}

:host(#{$prefix}-tabs) {
  @include focus-outline('reset');

  .#{$prefix}--tabs-trigger svg {
    block-size: auto;
    inline-size: auto;
  }
}

:host(#{$prefix}-tabs:focus) {
  .#{$prefix}--tabs-trigger {
    @include focus-outline('outline');
  }
}

:host(#{$prefix}-tabs[size='sm']) {
  @extend .#{$prefix}--layout--size-sm;
  --#{$prefix}-tabs-icon-only-badge-indicator-offset: #{$spacing-02};
}

:host(#{$prefix}-tabs[size='md']) {
  @extend .#{$prefix}--layout--size-md;
}

:host(#{$prefix}-tabs[type='contained'][size='lg']),
:host(#{$prefix}-tabs[vertical][size='lg']) {
  @extend .#{$prefix}--layout--size-lg;
}

:host(#{$prefix}-tabs[icon-size='default'])
  .#{$prefix}--tabs-nav-content-container,
:host(#{$prefix}-tabs.#{$prefix}--tabs__icon--default)
  .#{$prefix}--tabs-nav-content-container {
  overflow: visible;
  block-size: layout.size('height');
}

:host(#{$prefix}-tabs[icon-size='lg']) .#{$prefix}--tabs-nav-content-container,
:host(#{$prefix}-tabs.#{$prefix}--tabs__icon--lg)
  .#{$prefix}--tabs-nav-content-container {
  overflow: visible;
  block-size: $spacing-09;
}

:host(#{$prefix}-tabs[icon-size='default']),
:host(#{$prefix}-tabs[icon-size='lg']),
:host(#{$prefix}-tabs.#{$prefix}--tabs__icon--default),
:host(#{$prefix}-tabs.#{$prefix}--tabs__icon--lg) {
  overflow: visible;

  .#{$prefix}--tab--list {
    overflow: visible;
  }
}

:host(#{$prefix}-tabs[type='contained']) {
  .#{$prefix}--tab--overflow-nav-button {
    background-color: $layer-accent;
    inline-size: $spacing-09;

    &:hover {
      background-color: $layer-accent-hover;
    }

    &:active {
      background-color: $layer-accent-active;
    }
  }
}

:host(#{$prefix}-tabs[type='contained'][has-secondary-labels])
  .#{$prefix}--tabs-nav-content-container {
  block-size: $spacing-10;
}

:host(#{$prefix}-tabs[type='contained'][has-secondary-labels]) #{$prefix}-tab {
  block-size: $spacing-10;
}

:host(#{$prefix}-tab[type='contained'][secondary-label]) {
  block-size: $spacing-10;

  a.#{$prefix}--tabs__nav-link {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
    padding: 0 $spacing-05;
    block-size: $spacing-10;
    line-height: normal;
  }

  .#{$prefix}--tabs__nav-item-label-wrapper {
    flex-direction: row;
    align-items: center;
  }

  .#{$prefix}--tabs__nav-item-label {
    line-height: var(--cds-body-compact-01-line-height);
  }
}

:host(#{$prefix}-tab[type='contained'][secondary-label][selected]),
:host(#{$prefix}-tab[type='contained'][secondary-label][selected]:hover) {
  a.#{$prefix}--tabs__nav-link {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
    padding: 0 $spacing-05;
    line-height: normal;
  }
}

:host(#{$prefix}-tab[type='contained']) {
  .#{$prefix}--tabs__nav-item-secondary-label {
    @include type-style('label-01');

    display: block;
    overflow: hidden;
    color: $text-secondary;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

:host(#{$prefix}-tab[type='contained'][selected]) {
  .#{$prefix}--tabs__nav-item-secondary-label {
    color: $text-primary;
  }
}

:host(#{$prefix}-tab[type='contained'][disabled]) {
  .#{$prefix}--tabs__nav-item-secondary-label {
    color: $text-on-color-disabled;
  }
}

:host(#{$prefix}-tabs[type='contained'][full-width]) {
  display: flex;
  inline-size: 100%;

  .#{$prefix}--tabs-nav-content-container {
    overflow: visible;
    flex: 1 1 0%;
  }

  .#{$prefix}--tabs-nav-content,
  .#{$prefix}--tabs-nav,
  .#{$prefix}--tab--list {
    inline-size: 100%;
  }

  .#{$prefix}--tab--list {
    display: flex;
  }
}

:host(#{$prefix}-tabs[type='contained'][full-width]) #{$prefix}-tab {
  flex: 1 1 0%;
  min-inline-size: 0;

  .#{$prefix}--tabs__nav-link {
    overflow: hidden;
    inline-size: 100%;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

:host(#{$prefix}-tab),
:host(#{$prefix}-tab-skeleton) {
  @include layout.use('size', $default: 'md', $min: 'sm', $max: 'lg');

  display: flex;
  background: transparent;
  inline-size: 100%;

  .#{$prefix}--tabs__nav-item-label-wrapper {
    display: flex;
    align-items: inherit;
    gap: $spacing-03;
  }

  .#{$prefix}--tabs__nav-link {
    @include button-reset.reset($width: false);
    @include focus-outline('reset');
    @include type-style('body-compact-01');

    position: relative;
    overflow: hidden;

    align-items: center;
    padding: $spacing-04 $spacing-05 $spacing-03;
    border-block-end: $tab-underline-color;
    color: $text-secondary;
    inline-size: 100%;
    text-align: start;
    text-decoration: none;
    text-overflow: ellipsis;
    transition:
      border $duration-fast-01 motion(standard, productive),
      outline $duration-fast-01 motion(standard, productive);
    white-space: nowrap;

    &:focus,
    &:active {
      @include focus-outline('outline');
    }
  }

  outline: none;
}

:host(#{$prefix}-tab:not([type='contained']):not([vertical])) {
  margin-inline-end: convert.to-rem(1px);
}
:host(#{$prefix}-tab:not([type='contained'])) {
  .#{$prefix}--tabs__nav-link {
    display: flex;
    align-items: center;
    block-size: layout.size('height');
    padding-block: 0;
  }
}

:host(#{$prefix}-tab:not([type='contained']):not([vertical]):last-of-type) {
  margin-inline-end: 0;
}
:host(#{$prefix}-tab:not([type='contained']))
  + :host(#{$prefix}-tab:not([type='contained'])) {
  margin-inline-start: convert.to-rem(1px);
}
:host(#{$prefix}-tab[vertical]) {
  .#{$prefix}--tabs__nav-link {
    padding-block-end: $spacing-03;
    padding-block-start: $spacing-03;
  }
}

:host(#{$prefix}-tab[badge-indicator][icon-only]:not([icon-size='lg']))
  #{$prefix}-badge-indicator,
:host(
    #{$prefix}-tab[badge-indicator].#{$prefix}--tabs__nav-item--icon-only:not(
        .#{$prefix}--tabs__nav-item--icon-only__20
      )
  )
  #{$prefix}-badge-indicator {
  margin-block-start: var(
    --#{$prefix}-tabs-icon-only-badge-indicator-offset,
    #{$spacing-03}
  );
  margin-inline-end: var(
    --#{$prefix}-tabs-icon-only-badge-indicator-offset,
    #{$spacing-03}
  );
}

:host(#{$prefix}-tab[icon-only]),
:host(#{$prefix}-tab.#{$prefix}--tabs__nav-item--icon-only) {
  flex: 0 0 auto;
  block-size: layout.size('height');
  inline-size: layout.size('height');

  .#{$prefix}--tabs__nav-item-label-wrapper {
    display: flex;
  }

  #{$prefix}-tooltip {
    display: block;
    block-size: 100%;
    inline-size: 100%;
    --#{$prefix}-tooltip-padding-block: #{convert.to-rem(2px)};
    --#{$prefix}-popover-caret-width: #{convert.to-rem(8px)};
    --#{$prefix}-popover-caret-height: #{convert.to-rem(4px)};
    --#{$prefix}-popover-offset: #{convert.to-rem(8px)};
  }

  #{$prefix}-tooltip-content {
    --#{$prefix}-popover-offset: #{convert.to-rem(8px)};
  }

  #{$prefix}-tooltip::part(popover-container) {
    display: block;
    block-size: 100%;
    inline-size: 100%;
  }

  .#{$prefix}--tabs__nav-link {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    block-size: 100%;
    inline-size: 100%;
  }

  ::slotted(svg) {
    display: block;
    fill: currentColor;
  }
}

:host(#{$prefix}-tab[icon-only]:not([type='contained'])),
:host(
    #{$prefix}-tab.#{$prefix}--tabs__nav-item--icon-only:not([type='contained'])
  ) {
  .#{$prefix}--tabs__nav-item-label-wrapper {
    position: relative;
    inset-block-start: convert.to-rem(1px);
  }
}

:host(#{$prefix}-tab[icon-only][icon-size='lg']),
:host(#{$prefix}-tab.#{$prefix}--tabs__nav-item--icon-only__20) {
  block-size: $spacing-09;
  inline-size: $spacing-09;
}

:host(#{$prefix}-tab[selected]) {
  .#{$prefix}--tabs__nav-link {
    @include type-style('heading-compact-01');

    border-block-end: $spacing-01 solid $border-interactive;

    &,
    // Need to override Carbon core's non-selected focus color
    &:focus,
    &:active {
      color: $text-primary;
    }
  }

  display: flex;
  background-color: transparent;
  transition: color $duration-fast-01 motion(standard, productive);

  &:hover {
    background-color: transparent;
  }
}

:host(
    #{$prefix}-tab:not([type='contained']):hover:not([selected]):not(
        [disabled]
      ):not([vertical])
  ) {
  background-color: transparent;

  a.#{$prefix}--tabs__nav-link {
    border-block-end: $tab-underline-color-hover;
    color: $text-primary;
  }
}

:host(#{$prefix}-tab[icon-only]:hover),
:host(#{$prefix}-tab.#{$prefix}--tabs__nav-item--icon-only:hover) {
  box-shadow: none;
}

:host(#{$prefix}-tabs[type='contained'])
  .#{$prefix}--tabs-nav-content-container {
  block-size: layout.size('height');
}

:host(#{$prefix}-tab[type='contained']) {
  background-color: $layer-accent-01;

  a.#{$prefix}--tabs__nav-link {
    padding: $spacing-03 $spacing-05;
    block-size: layout.size('height');
    // height - vertical padding
    line-height: calc(#{layout.size('height')} - (#{$spacing-03} * 2));
  }
}

:host(#{$prefix}-tab[type='contained']),
:host(#{$prefix}-tab[type='contained']:hover) {
  a.#{$prefix}--tabs__nav-link {
    border-block-end: none;
    // Draws the border without affecting the inner-content
    box-shadow: rem(-1px) 0 0 0 $border-strong;
  }
}

:host(#{$prefix}-tab[type='contained'][hide-divider])
  a.#{$prefix}--tabs__nav-link {
  box-shadow: rem(-1px) 0 0 0 transparent;
}

// `[role]` is only for specificity.
// We have `:not()` usage in the corresponding Carbon core style
// which puts specificity of "specific" scenario though the style is for "regular" scenario
:host(#{$prefix}-tab[disabled][role]),
:host(#{$prefix}-tab[disabled][role]:hover) {
  background-color: transparent;
  box-shadow: none;
  cursor: not-allowed;
  outline: none;

  .#{$prefix}--tabs__nav-link {
    border-block-end: $tab-underline-color;
    color: $tab-text-disabled;
    outline: none;
    pointer-events: none;
  }
}

:host(#{$prefix}-tab[type='contained'][disabled][role])
  .#{$prefix}--tabs__nav-link {
  background-color: $button-disabled;
  border-block-end: none;
  color: $text-on-color-disabled;
}

:host(#{$prefix}-tab[type='contained'][selected]),
:host(#{$prefix}-tab[type='contained'][selected]:hover) {
  background-color: $layer-01;

  .#{$prefix}--tabs__nav-link {
    border-block-end: none;
    // Draws the border without affecting the inner-content
    box-shadow: inset 0 $spacing-01 0 0 $interactive;
    // height - vertical padding
    line-height: calc(#{layout.size('height')} - (#{$spacing-03} * 2));
  }

  .#{$prefix}--tabs__nav-link:focus,
  .#{$prefix}--tabs__nav-link:active {
    box-shadow: none;
  }
}

:host(#{$prefix}-tab[type='contained']:hover) {
  background-color: $layer-accent-01;
}
:host(#{$prefix}-tab[type='contained']) {
  .#{$prefix}--tabs__nav-link:hover {
    background-color: $layer-accent-hover;
  }
}

// Disabled tab never gets selected, but we guard for manual addition of `selected` attribute
:host(#{$prefix}-tab[disabled][selected]),
:host(#{$prefix}-tab[disabled][selected]:hover),
:host(#{$prefix}-tab[disabled][in-focus][selected]),
:host(#{$prefix}-tab[disabled][in-focus][selected]:hover) {
  display: flex;
  background-color: transparent;
  box-shadow: none;

  @include focus-outline('reset');

  .#{$prefix}--tabs__nav-link {
    @include type-style('body-short-01');

    border-block-end: $tab-underline-color;

    color: $tab-text-disabled;

    &:focus,
    &:active {
      border-block-end-width: 3px;
    }
  }
}

:host(#{$prefix}-tabs-skeleton) .#{$prefix}--tabs-trigger {
  @include skeleton;

  inline-size: rem(100px);
}

:host(#{$prefix}-tab-skeleton) {
  margin-inline-start: $spacing-01;

  .#{$prefix}--tabs__nav-link {
    display: flex;
    align-items: center;
    padding: 0 layout.density('padding-inline');
    block-size: 100%;
    border-block-end: 2px solid $skeleton-element;
    inline-size: 10rem;
  }

  .#{$prefix}--tabs__nav-item {
    @include reset;

    position: relative;
    display: flex;
    flex: 1 0 auto;
    padding: 0;
    cursor: pointer;
    transition: background-color $duration-fast-01 motion(standard, productive);
  }

  span {
    @include skeleton;

    display: block;
    block-size: convert.to-rem(14px);
    inline-size: 100%;
  }
}

:host(#{$prefix}-tab-skeleton) {
  @extend .#{$prefix}--tabs__nav-item;
}

:host(#{$prefix}-tabs-skeleton) {
  @extend .#{$prefix}--tabs;
  @extend .#{$prefix}--skeleton;
}

:host(#{$prefix}-tabs-skeleton[contained]) {
  @extend .#{$prefix}--tabs--contained;
}

:host(#{$prefix}-tab-skeleton:first-of-type) {
  margin-inline-start: 0;
}

// Windows HCM fix
:host(#{$prefix}-tab[selected]) .#{$prefix}--tabs__nav-link {
  @include high-contrast-mode {
    background-color: SelectedItem;
  }
}

:host(#{$prefix}-tab[vertical]) .#{$prefix}--tabs__nav-link {
  display: flex;
  align-items: center;
  block-size: 100%;
  border-block-end: 1px solid $border-subtle;
}

:host(#{$prefix}-tab[vertical][selected]) .#{$prefix}--tabs__nav-link {
  border-block-end: 1px solid $border-subtle;
}

:host(#{$prefix}-tab[vertical][disabled]) .#{$prefix}--tabs__nav-link {
  border-block-end: 1px solid $border-subtle;
}

//-----------------------------
// Vertical Tabs Wrapper
//-----------------------------

:host(#{$prefix}-tabs-vertical) {
  @include emit-layout-tokens();
  @include layout.use('density', $default: 'normal');

  grid-column: span 2;
  max-block-size: none;

  &.#{$prefix}--css-grid {
    box-shadow: inset -1px 0 $border-subtle;
  }

  ::slotted(#{$prefix}-tabs) {
    grid-column: span 2;

    @include breakpoint(lg) {
      grid-column: span 4;
    }
  }

  // Shadow-DOM wrapper for the panel slot — styled directly (no ::slotted needed)
  .#{$prefix}-panel-container {
    @include update_fields_on_layer;

    background: $layer;
    grid-column: 3 / -1;
    overflow-y: auto;

    @include breakpoint(lg) {
      grid-column: 5 / -1;
    }
  }
}

// Slotted tab panel divs — match React's cds--tab-content styles
:host(#{$prefix}-tabs-vertical) ::slotted([role='tabpanel']) {
  // stylelint-disable-next-line declaration-no-important
  padding: layout.density('padding-inline') !important;
  outline: none;
}

:host(#{$prefix}-tabs-vertical)
  .panel-container
  ::slotted([role='tabpanel']:focus) {
  @include focus-outline('outline');
}

// cds-tabs when slotted inside cds-tabs-vertical (slot="tabs")
:host(#{$prefix}-tabs-vertical) ::slotted(#{$prefix}-tabs) {
  background: $layer;
  box-shadow: inset -1px 0 $border-subtle;
  max-block-size: none;
}

// Internal styles for cds-tabs when inside cds-tabs-vertical
// These are applied via a CSS custom property / attribute set by the wrapper
:host(#{$prefix}-tabs[vertical]) {
  // Default line-clamp for vertical tabs
  --#{$prefix}-tabs-vertical-line-clamp: 2;

  .#{$prefix}--tabs-nav-content-container {
    block-size: 100%;
    overflow-x: hidden;
    overflow-y: auto;
  }

  .#{$prefix}--tabs-nav-content {
    position: relative;
    block-size: 100%;
  }

  .#{$prefix}--tabs-nav {
    position: relative;
  }

  .#{$prefix}--tab--list {
    display: flex;
    flex-direction: column;
  }

  .#{$prefix}--tab--overflow-nav-button {
    display: none;
  }
}

// Size-specific line-clamp overrides for vertical tabs
:host(#{$prefix}-tabs[size='sm'][vertical]) {
  --#{$prefix}-tabs-vertical-line-clamp: 1;
}

:host(#{$prefix}-tab[vertical]) {
  flex: none;
  background-color: $layer-01;
  block-size: var(--#{$prefix}-layout-size-height, $spacing-10);
  border-inline-end: 1px solid $border-subtle;
  box-shadow: inset 3px 0 0 0 $border-subtle;
  inline-size: 100%;

  .#{$prefix}--tabs__nav-item-label {
    display: -webkit-box;
    overflow: hidden;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: var(--#{$prefix}-tabs-vertical-line-clamp);
    line-height: var(--cds-body-compact-01-line-height);
    text-overflow: ellipsis;
    white-space: normal;
  }
}

:host(#{$prefix}-tab[vertical][disabled]) {
  border-inline-end: 1px solid $border-subtle;
  box-shadow: inset 3px 0 0 0 $border-subtle;
}

:host(#{$prefix}-tab[vertical]:hover),
:host(#{$prefix}-tab[vertical][disabled]:hover) {
  .#{$prefix}--tabs__nav-link {
    border-block-end: 1px solid $border-subtle;
  }
}

:host(#{$prefix}-tab[vertical][selected]) {
  border-inline: none;
  box-shadow: inset 3px 0 0 0 $border-interactive;
}

:host(#{$prefix}-tab[vertical]:not([selected]):not([disabled]):hover) {
  background-color: $layer-hover;
  box-shadow: inset 3px 0 0 0 $border-strong;
}
:host(#{$prefix}-tab) {
  .#{$prefix}--tabs__nav-link--dismissable {
    display: flex;
    align-items: flex-start;
    padding-inline-end: $spacing-08;
  }
  .#{$prefix}--tabs--dismissable.#{$prefix}--tabs--contained {
    padding-inline-end: calc($spacing-09 - 1px);
  }
}
:host(#{$prefix}-tab[type='contained']) {
  .#{$prefix}--tabs__nav-link.#{$prefix}--tabs__nav-link--dismissable {
    padding-inline-end: calc($spacing-09 - 1px);
  }
}
:host(#{$prefix}-tab) {
  .#{$prefix}--tabs__nav-item--close {
    position: relative;
    display: flex;
    align-items: center;
    inset-inline-start: calc(-#{$spacing-04} - 1px);
    margin-inline-start: calc(-#{$spacing-06} + 1px);

    @if flags.enabled('enable-v12-release') {
      @include button-radius.radius($border-radius-00);
    }

    &[disabled] {
      pointer-events: none;
    }
  }
  .#{$prefix}--tabs__nav-item--close--hidden {
    display: none;
  }
  .#{$prefix}--tabs__nav-item--close::part(button) {
    @include button-reset.reset();

    block-size: convert.to-rem(24px);
    inline-size: convert.to-rem(24px);
    padding-block: $spacing-02;
    padding-inline: $spacing-02;
    pointer-events: inherit;

    svg {
      block-size: convert.to-rem(16px);
      fill: $text-secondary;
      inline-size: convert.to-rem(16px);
    }

    svg:hover {
      fill: $icon-primary;
    }

    &:hover {
      background-color: $layer-hover;
    }

    &:focus,
    &:active {
      @include focus-outline('outline');
    }
  }
}

