@use '@carbon/styles/scss/config' as *;
@use '@carbon/styles/scss/type' as *;
@use '@carbon/styles/scss/utilities';
@use '@carbon/styles/scss/utilities/custom-property' as *;
@use '@carbon/styles/scss/spacing' as *;
@use '@carbon/styles/scss/theme' as *;
@use '@carbon/styles/scss/type' as *;
@use '@carbon/styles/scss/components/toggletip/index' as *;
@use '@carbon/styles/scss/utilities/button-reset';

:host(#{$prefix}-toggletip),
:host(#{$prefix}-ai-label),
:host(#{$prefix}-slug) {
  // TODO: audit
  @extend .#{$prefix}--toggletip;

  display: flex;
  align-items: center;
  justify-content: center;

  outline: none;
}

:host(#{$prefix}-toggletip[open]:not([autoalign])) {
  // Keep the caret fill on `::after` so the container does not render as a
  // block.
  .#{$prefix}--popover-caret {
    background: transparent;

    &::after {
      background-color: $background-inverse;
    }
  }
}

:host(#{$prefix}-toggletip[open][autoalign]) {
  // `autoalign` uses the rotated caret container as the visible shape.
  .#{$prefix}--popover-caret {
    background-color: $background-inverse;
  }
}

:host(#{$prefix}-ai-label[open][autoalign]),
:host(#{$prefix}-slug[open][autoalign]),
:host(#{$prefix}-toggletip[open][autoalign]) {
  .#{$prefix}--popover-content {
    display: block;

    @include declaration('popover-background-color', $background-inverse);

    @include declaration('popover-text-color', $text-inverse);
  }
}

