@use '@carbon/styles/scss/config' as *;
@use '@carbon/styles/scss/components/tooltip';
@use '@carbon/styles/scss/spacing' as *;
@use '@carbon/styles/scss/utilities/custom-property';
@use '@carbon/styles/scss/utilities/layout';
@use '@carbon/styles/scss/theme' as *;
@use '@carbon/styles/scss/utilities/convert' as *;

// For some reason `#{prefix}-tooltip` doesn't work here, will need to investigate
:host(#{$prefix}-tooltip[data-table]) {
  display: contents;

  &:hover {
    ::slotted(button) {
      /* stylelint-disable-next-line declaration-no-important */
      background-color: $layer-selected-hover !important;
    }
  }
}

:host(#{$prefix}-tooltip[data-table][size='xs']),
:host(#{$prefix}-tooltip[data-table][size='sm']) {
  ::slotted(button) {
    /* stylelint-disable-next-line declaration-no-important */
    block-size: calc(100% + 1px) !important;
  }
}

:host(#{$prefix}-tooltip[toolbar-action]) {
  ::slotted(button) {
    /* stylelint-disable-next-line declaration-no-important */
    outline: none !important;
  }
}

:host(#{$prefix}-tooltip) {
  ::slotted(button.#{$prefix}--overflow-menu:focus) {
    background-color: $background-active;
  }
}

:host(#{$prefix}-tooltip[data-programmatic-focus]) {
  ::slotted(button.#{$prefix}--overflow-menu) {
    background-color: $background-active;
  }
}

:host(#{$prefix}-tooltip-content) {
  word-break: break-word;

  ::slotted(.#{$prefix}-tooltip-content) {
    @extend .#{$prefix}--tooltip-content;
  }
}

// Definition tooltip
:host(#{$prefix}-definition-tooltip) {
  #{$prefix}-popover {
    display: flex;
  }

  #{$prefix}-popover-content::part(content) {
    @extend .#{$prefix}--definition-tooltip;

    padding-block: custom-property.get-var(
      'tooltip-padding-block',
      to-rem(8px)
    );
  }
}

// Password input "Show/Hide Password" tooltip
:host(#{$prefix}-tooltip-content[toggle-password-tooltip-content]) {
  .#{$prefix}--popover {
    @include layout.use('size', $default: 'md', $min: 'xs', $max: 'lg');

    gap: $spacing-02;
    inset-inline-start: calc(-1 * layout.size('height'));
  }
}

