import { LitElement, html } from 'lit';
import { property, state } from 'lit/decorators.js';
import { classMap } from 'lit/directives/class-map.js';
import { prefix } from '../../globals/settings';
import HostListenerMixin from '../../globals/mixins/host-listener';
import { carbonElement as customElement } from '../../globals/decorators/carbon-element';
import styles from './user-avatar.scss?lit';
import '../tooltip/index';
import User from '@carbon/icons/es/user/16';
import { iconLoader } from '../../globals/internal/icon-loader';

const blockClass = `${prefix}--user-avatar`;

/**
 * User Avatar.
 *
 * @element cds-user-avatar
 */

@customElement(`${prefix}-user-avatar`)
class CDSUserAvatar extends HostListenerMixin(LitElement) {
  /**
   * Specify the text of the tooltip.
   * Can be string
   */
  @property({ reflect: true, attribute: 'tooltip-text' })
  tooltipText;

  /**
   * Specify the alignment of the tooltip.
   */
  @property({ reflect: true, attribute: 'tooltip-alignment' })
  tooltipAlignment = 'bottom';

  /**
   * When passing the name prop, either send the initials to be used or the
   * user's full name. The first two capital letters of the user's name will be
   * used as the name.
   */
  @property({ reflect: true })
  name;

  /**
   * Set the size of the avatar circle.
   */
  @property({ reflect: true })
  size = 'md';

  /**
   * When passing the image prop, supply a full path to the image to be
   * displayed.
   */
  @property({ reflect: true })
  image;

  /**
   * When passing the image prop use the imageDescription prop to describe the
   * image for screen reader.
   */
  @property({ reflect: true, attribute: 'image-description' })
  imageDescription;

  /**
   * Specify the background color for UserAvatar.
   */
  @property({ reflect: true, attribute: 'background-color' })
  backgroundColor = 'order-1-cyan';

  /**
   * Set theme in which the component will be rendered.
   */
  @property({ reflect: true })
  theme;

  @state()
  private _hasRenderIcon = false;

  private _observerMutation: MutationObserver | null = null;

  private _handleMutation = () => {
    this._hasRenderIcon = Boolean(this.querySelector('[slot="rendericon"]'));
  };

  connectedCallback() {
    super.connectedCallback();
    this._hasRenderIcon = Boolean(this.querySelector('[slot="rendericon"]'));
    this._observerMutation = new MutationObserver(this._handleMutation);
    this._observerMutation.observe(this, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['slot'],
    });
  }

  disconnectedCallback() {
    if (this._observerMutation) {
      this._observerMutation.disconnect();
      this._observerMutation = null;
    }
    super.disconnectedCallback();
  }

  private _onSlotChange() {
    this._hasRenderIcon = Boolean(this.querySelector('[slot="rendericon"]'));
  }

  render() {
    const getItem = () => {
      if (this.image) {
        const imageClasses = classMap({
          [`${blockClass}__photo`]: true,
          [`${blockClass}__photo--${this.size}`]: this.size,
        });
        return html` <img
          alt="${this.imageDescription ?? ''}"
          src="${this.image}"
          class="${imageClasses}" />`;
      }
      if (this._hasRenderIcon) {
        return html`<slot
          name="rendericon"
          @slotchange=${this._onSlotChange}></slot>`;
      }
      if (this.name) {
        const parts = this.name?.split(' ') || [];
        const firstChar = parts[0].charAt(0).toUpperCase();
        const secondChar = parts[0].charAt(1).toUpperCase();
        if (parts.length === 1) {
          return firstChar + secondChar;
        }
        const lastChar = parts[parts.length - 1].charAt(0).toUpperCase();
        const initials = [firstChar];
        if (lastChar) {
          initials.push(lastChar);
        }

        return ''.concat(...initials);
      }
      return html`${iconLoader(User, { slot: 'rendericon' })} `;
    };

    const { tooltipText, tooltipAlignment, size, backgroundColor, theme } =
      this;
    const classes = classMap({
      [`${blockClass}`]: true,
      [`${blockClass}--${size}`]: size,
      [`${blockClass}--${backgroundColor}`]: backgroundColor,
      [`${blockClass}--${theme}`]: theme,
    });

    const Avatar = () => html`<div class="${classes}">${getItem()}</div>`;

    if (tooltipText) {
      return html`<cds-tooltip
        align=${tooltipAlignment}
        class=${`${blockClass}__tooltip ${prefix}--icon-tooltip`}>
        <button
          class=${`${blockClass}__tooltip-trigger`}
          type="button"
          aria-label=${tooltipText}>
          ${Avatar()}
        </button>
        <cds-tooltip-content class=${`${blockClass}__tooltip-content`}>
          ${tooltipText}
        </cds-tooltip-content>
      </cds-tooltip>`;
    } else {
      return html` ${Avatar()}`;
    }
  }

  static shadowRootOptions = {
    ...LitElement.shadowRootOptions,
    delegatesFocus: true,
  };

  static styles = styles;
}

export default CDSUserAvatar;

