@use '@carbon/ibm-products-web-components/scss/components/coachmark/coachmark-tagline/coachmark-tagline.scss';
@use '@carbon/styles/scss/spacing' as *;
@use '@carbon/styles/scss/type';
@use '@carbon/styles/scss/motion' as *;
@use '@carbon/styles/scss/theme' as *;
@include carousel.carousel();
@include carousel.wrapperStyles();

$prefix: 'c4p';
$carbon-prefix: 'cds';
$stack-home-class: 'coachmark-stacked-home';
$stacked-coachmark: 'stacked-coachmark';

/* Parent coachmark positioning */
/* stylelint-disable-next-line selector-type-no-unknown */
.parent-coachmark #{$prefix}-coachmark::part(popover) {
  inset-block-end: 0;
  inset-inline-end: $spacing-13;
}

/* Parent coachmark content transition */
/* stylelint-disable-next-line selector-type-no-unknown */
.parent-coachmark #{$prefix}-coachmark::part(content) {
  transition: height $duration-fast-02 motion(exit, productive);

  @media (prefers-reduced-motion) {
    transition: none;
  }
}

/* Child coachmark positioning - match parent position */
/* stylelint-disable-next-line selector-type-no-unknown */
.stacked_element_content::part(popover) {
  inset-block-end: 0;
  inset-inline-end: $spacing-13;
  transform: translateY(100vh);
  transition: transform $duration-fast-02 motion(exit, productive);
  visibility: hidden;

  @media (prefers-reduced-motion) {
    transition: none;
  }
}

/* Trigger animation when is-visible class is applied */
/* stylelint-disable-next-line selector-type-no-unknown */
.stacked_element_content.is-visible::part(popover) {
  transform: translateY(0);
  visibility: visible;
}

/* stylelint-disable-next-line selector-type-no-unknown */
#{$prefix}-coachmark::part(popover-container) {
  position: absolute;
}

/* stylelint-disable-next-line selector-type-no-unknown */
#{$prefix}-coachmark::part(content) {
  inset-block-start: 0px;
  inline-size: 18rem;
}

/* stylelint-disable-next-line selector-type-no-unknown */
#{$prefix}-coachmark-body {
  display: flex;
  flex-direction: column;
  inline-size: 16rem !important;

  h2 {
    @include type.type-style('productive-heading-02');

    margin: 0 0 $spacing-03;
  }

  p {
    @include type.type-style('body-01');

    margin: 0 0 $spacing-03;
  }
  /* stylelint-disable-next-line selector-type-no-unknown */
  #{$carbon-prefix}-button {
    align-self: flex-end;
    justify-content: flex-end;
  }

  .exampleCarouselWrapper {
    // Remove fixed height to allow carousel to use max height of all pages
    margin-inline-end: $spacing-05;
  }

  .coachmark-stacked-home__nav-links {
    margin-inline-start: calc(-1 * $spacing-05);
  }

}

.carouselControlWrapper__footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;   
}

.carouselControlWrapper--buttons {
  display: flex;
  gap: $spacing-03;
}

.carouselControlWrapper--controls-progress {
  justify-self: flex-start;
  margin-inline-end: auto;
  @include type.type-style('helper-text-01');
}

.coachmark-stacked-home--scaled-content,
.coachmark-stacked-home--scaled-content::part(popover-container) {
  opacity: 0.8 !important;
  transform: scale(0.9) !important;
  transform-origin: top center !important;
  transition: transform $duration-moderate-02 motion(exit, productive),
    opacity $duration-moderate-02 motion(exit, productive) !important;
  pointer-events: none !important;
}

.coachmark-stacked-home--unscaled-content,
.coachmark-stacked-home--unscaled-content::part(popover-container) {
  opacity: 1 !important;
}

/* Update coachmark body width */
/* stylelint-disable-next-line selector-type-no-unknown */
#{$prefix}-coachmark-body {
  inline-size: 18rem;
}

/* Fix for carousel views blocking button clicks */
.carousel__view {
  pointer-events: none;

  * {
    pointer-events: auto;
  }
}

.carousel__view > h2 {
  @include type.type-style('productive-heading-02');
  margin: 0 0 $spacing-03;
}

.carousel__view > p {
  @include type.type-style('body-01');
}

/* Carousel controls */
.carouselControlWrapper__footer {
  padding-block-start: $spacing-05;
}

/* Parent coachmark home styles */
.#{$stack-home-class} {
  &-element {
    margin-block-end: $spacing-03;
  }

  &__title {
    @include type.type-style('productive-heading-02');
    margin: 0 0 $spacing-03;
  }

  &__body {
    @include type.type-style('body-01');
  }

  &__footer {
    margin-block-start: $spacing-05;
  }
}

/* Stacked child coachmark styles */
.#{$stacked-coachmark} {
  &__content {
    display: flex;
    flex-direction: column;
  }

  &__title {
    @include type.type-style('productive-heading-02');
    margin: 0 0 $spacing-03;
  }

  &__body {
    @include type.type-style('body-01');
    margin: 0 0 $spacing-03;
  }

  &__button {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding-block-start: $spacing-05;
  }
}

