class EditApiKeyModalError extends HostListenerMixin(LitElement) {
  @property({ type: Boolean })
  error = false;

  @state()
  loading = false;

  @state()
  editing = true;

  @state()
  copyError = false;

  @state()
  successful = false;

  @state()
  editSuccess = false;

  @state()
  apiKeyName: string = '';

  @state()
  hasDownloadLink = false;

  @state()
  successMessage: string = '';

  @state()
  apiKeyLoaded: boolean = false;

  private apiKey: string = '';
  private nameRequired = true;
  private textInputRef: HTMLElement | null = null;

  protected firstUpdated() {
    this.apiKeyName = 'test_key_1';
  }

  updated(changedProperties: Map<string, any>) {
    super.updated(changedProperties);
    if (changedProperties.has('error') && this.error && this.textInputRef) {
      setTimeout(() => {
        const input = this.textInputRef?.shadowRoot?.querySelector('input');
        input?.focus();
      }, 0);
    }
  }
  private _inputHandler(e: Event) {
    this.apiKeyName = (e.target as HTMLInputElement).value;
  }

  private onCloseHandler() {
    this.apiKeyName = '';
    this.apiKey = '';
  }

  private wait = (ms: number) =>
    new Promise((resolve) => setTimeout(resolve, ms));

