    if (this.apiKeyLoaded) {
      try {
        await navigator.clipboard.writeText(this.apiKey);
      } catch (e) {
        this.copyError = true;
      }
    } else {
      this.error = false;
      this.loading = true;
      await this.wait(1000);
      this.error = true;
      if (this.error) {
        this.error = true;
      } else {
        this.editSuccess = true;
      }
      this.loading = false;
      this.requestUpdate();
