const blockClass = `c4p--apikey-modal`;

/**
 * GenerateApiKeyModal.
 *
 * @element generate-apikey-modal
 *
 * */

@customElement(`generate-apikey-modal`)
class GenerateApiKeyModal extends HostListenerMixin(LitElement) {
  @property({ type: Boolean })
  error = false;

  @state()
  loading = false;

  @state()
  editing = false;

  @state()
  copyError = false;

  @state()
  successful = false;

  @state()
  editSuccess = false;

  @state()
  apiKeyName: string = '';

  @state()
  hasDownloadLink = false;

  @state()
  successMessage: string = '';

  @state()
  apiKeyLoaded: boolean = false;

  private apiKey: string = '';
  private nameRequired = true;
  private passwordInputRef: HTMLElement | null = null;

  private _inputHandler(e: Event) {
    this.apiKeyName = (e.target as HTMLInputElement).value;
  }

  updated(changedProperties: Map<string, any>) {
    super.updated(changedProperties);
    if (changedProperties.has('apiKeyLoaded') && this.apiKeyLoaded && this.passwordInputRef) {
      setTimeout(() => {
        const input = this.passwordInputRef?.shadowRoot?.querySelector('input');
        input?.focus();
      }, 0);
    }
  }

  private onCloseHandler() {
    this.apiKeyName = '';
    this.apiKey = '';
  }

  private wait = (ms: number) =>
    new Promise((resolve) => setTimeout(resolve, ms));

  private async _submitHandler(_e: Event): Promise<void> {
    if (this.apiKeyLoaded) {
      try {
        await navigator.clipboard.writeText(this.apiKey);
      } catch (e) {
        this.copyError = true;
      }
    } else {
      this.error = false;
      this.loading = true;
      await this.wait(1000);
      if (this.error) {
        this.error = true;
      } else {
        this.apiKey = '111-111-111-111';
      }
      this.loading = false;
      this.requestUpdate();
    }
  }

  private isPrimaryButtonDisabled = () => {
    if (this.loading) {
      return true;
    }
    if (this.nameRequired && !this.apiKeyName) {
      return true;
    }
    return false;
  };

  render() {
    let modalRef: HTMLElement | null = null;
    this.apiKeyLoaded = Boolean(this.apiKey && !this.loading);
    this.hasDownloadLink = true;

    return html`
      <style>
        ${styles}
      </style>
      <cds-button
        kind="primary"
        @click=${() => modalRef?.setAttribute('open', '')}
      >
