export declare type Constructor<T> = {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- https://github.com/carbon-design-system/carbon/issues/20452
  new (...args: any[]): T;
};

type Finisher =
  | (<T>(clazz: Constructor<T>) => Constructor<T>)
  | (<T>(clazz: Constructor<T>) => void);

export interface ClassDescriptor {
  kind: 'class';
  elements: ClassElement[];
  finisher?: Finisher;
}

export interface ClassElement {
  kind: 'field' | 'method';
  key: PropertyKey;
  placement: 'static' | 'prototype' | 'own';
  initializer?: () => unknown;
  extras?: ClassElement[];
  finisher?: Finisher;
  descriptor?: PropertyDescriptor;
}

/**
 * Allow for custom element classes with private constructors
 */
type CustomElementClass = Omit<typeof HTMLElement, 'new'>;

const legacyCustomElement = (tagName: string, clazz: CustomElementClass) => {
  try {
    customElements.define(tagName, clazz as CustomElementConstructor);
  } catch {
    // eslint-disable-next-line no-console
    console.warn(`Attempting to re-define ${tagName}`);
  }
  // Cast as any because TS doesn't recognize the return type as being a
  // subtype of the decorated class when clazz is typed as
  // `Constructor<HTMLElement>` for some reason.
  // `Constructor<HTMLElement>` is helpful to make sure the decorator is
  // applied to elements however.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return clazz as any;
};

const standardCustomElement = (
  tagName: string,
  descriptor: ClassDescriptor
) => {
  const { kind, elements } = descriptor;
  return {
    kind,
    elements,
    // This callback is called once the class is otherwise fully defined
    finisher(clazz: Constructor<HTMLElement>) {
      try {
        customElements.define(tagName, clazz);
      } catch {
        // eslint-disable-next-line no-console
        console.warn(`Attempting to re-define ${tagName}`);
      }
    },
  };
};

/**
 * Class decorator factory that defines the decorated class as a custom element.
 *
 * ```js
 * @customElement('my-element')
 * class MyElement extends LitElement {
 *   render() {
 *     return html``;
 *   }
 * }
 * ```
 *
 * @deprecated The `carbonElement` decorator is deprecated and will be removed in
 *   v3. In v3, `@carbon/web-components` moves to pure component
 *   classes (`static is = '${prefix}-name'`) with opt-in registration via
 *   `defineCustomElement`, and this self-registering decorator is removed. If you
 *   author your own custom elements with it, migrate to Lit's `customElement`
 *   (`import { customElement } from 'lit/decorators.js'`). See the v3 migration
 *   guide:
 *   https://github.com/carbon-design-system/carbon/blob/main/docs/guides/cwc-v3-migration.md#the-carbonelement-decorator-is-removed
 * @category Decorator
 * @param tagName The tag name of the custom element to define.
 */
export const carbonElement =
  (tagName: string) =>
  (classOrDescriptor: CustomElementClass | ClassDescriptor) =>
    typeof classOrDescriptor === 'function'
      ? legacyCustomElement(tagName, classOrDescriptor)
      : standardCustomElement(tagName, classOrDescriptor as ClassDescriptor);

