Action buttons example, this brings everything together by adding the ability to
move between steps via `StepInstance.handleNext()` and
`StepInstance.handlePrevious()`, as well as showing how to reset via
`StepInstance.reset()` if the cancel button is clicked. This will reset the form
state and current step.

```ts
@customElement('my-stepped-component')
export class MySteppedComponent extends LitElement {
  @state()
  private _open: boolean = false;

  @state()
  private _email: string = '';

  @state()
  private _city: string = '';

  @state()
  private _state: string = '';

  private _stepInfo = new StepInstance(this);

  connectedCallback() {
    super.connectedCallback();
    this._stepInfo.updateTotalStepCount = 3;
  }

  private _handleCancelButton() {
    this._open = false;
    this._stepInfo.reset();
  }

  private _handleBackButton() {
    const { currentStep } = this._stepInfo.data;
    if (currentStep === 0) {
      return;
    }
    return this._stepInfo.handlePrevious();
  }

  private _handleNextButton() {
    const { currentStep, totalSteps } = this._stepInfo.data;
    if (currentStep + 1 === totalSteps) {
      this._open = false;
      this._stepInfo.reset();
      return;
    }
    return this._stepInfo.handleNext();
  }

  private _handleEmailInput(e: Event) {
    const savedFormState = structuredClone(
      this._stepInfo.data.formState
    ) as FormStateType;
    savedFormState.email = (e.target as HTMLInputElement).value;
    this._stepInfo.updateFormState = savedFormState;
  }

  render() {
    const { totalSteps, currentStep } = this._stepInfo.data;
    return html`
      <cds-tearsheet
        class="step-tearsheet-with-util"
        selector-primary-focus="#tearsheet-story-text-input-a"
        ?open=${this._open}
        variant="wide"
        prevent-close-on-click-outside
        @cds-tearsheet-closed=${this._handleCancelButton}>
        <cds-tearsheet-body>
          <div slot="main-content">
            ${currentStep === 0
              ? html` <cds-text-input
                  label="Email"
                  id="tearsheet-story-text-input-a"
                  value=${this._email}
                  @input="${this._handleEmailInput}"></cds-text-input>`
              : nothing}
            ${currentStep === 1 ? html`step 2` : nothing}
            ${currentStep === 2 ? html`step 3` : nothing}
            ${currentStep === 3 ? html`step 4` : nothing}
          </div>
        </cds-tearsheet-body>
        <cds-tearsheet-footer
          .actions="${[
            {
              kind: 'ghost',
              label: 'Cancel',
              onClick: () => this._handleCancelButton(),
            },
            {
              kind: 'secondary',
              label: 'Back',
              onClick: () => this._handleBackButton(),
            },
            {
              kind: 'primary',
              label: currentStep + 1 < totalSteps ? 'Next' : 'Submit',
              onClick: () => this._handleNextButton(),
            },
          ]}"></cds-tearsheet-footer>
      </cds-tearsheet>
    `;
  }
}
```

